{"command":"cat > fselect.py <<'PYEOF'
#!/usr/bin/env python3
"""fselect reimplementation: find files with SQL-like queries.

Written from scratch based on observed behaviour of the reference tool.
"""
import os, sys, re, stat, math, time, datetime, hashlib, base64, random
import pwd, grp
from collections import deque

VERSION = "0.10.0"

# ---------------------------------------------------------------------------
# Global state (mirrors the original's process-wide flags)
# ---------------------------------------------------------------------------
class State:
    no_color = False          # colour disabled for errors/help
    no_errors = False         # suppress error reporting
    had_io_error = False      # exit code 1
    had_parse_error = False   # exit code 2
    us_dates = False
    config = None
    errors_on = True          # interactive mode toggle (combined with no_errors)

state = State()

def colorize_subject(s):
    if state.no_color:
        return s
    return "\x1b[33m" + s + "\x1b[0m"

def report(subject, message, io_error=True, count_exit=True):
    """Print an error like the original: '<yellow>subject</>: message'."""
    if count_exit and io_error:
        state.had_io_error = True
    if not state.no_errors and state.errors_on:
        try:
            sys.stderr.write("%s: %s\n" % (colorize_subject(subject), message))
            sys.stderr.flush()
        except Exception:
            pass

def report_parse(message):
    state.had_parse_error = True
    if not state.no_errors and state.errors_on:
        try:
            sys.stderr.write("%s: %s\n" % (colorize_subject("query"), message))
            sys.stderr.flush()
        except Exception:
            pass

class ParseError_(Exception):
    def __init__(self, message):
        self.message = message

class EvalError_(Exception):
    """Per-file evaluation error (Division by zero, Can't parse datetime...)"""
    def __init__(self, message, subject=None):
        self.message = message
        self.subject = subject  # None -> use file path

class Config:
    def __init__(self):
        self.no_color = False
        self.gitignore = False
        self.hgignore = False
        self.dockerignore = False
        self.is_zip_archive = [".zip", ".jar", ".war", ".ear"]
        self.is_archive = [".7z", ".bz2", ".bzip2", ".gz", ".gzip", ".lz", ".rar", ".tar", ".xz", ".zip"]
        self.is_audio = [".aac", ".aiff", ".amr", ".flac", ".gsm", ".m4a", ".m4b", ".m4p", ".mp3", ".ogg", ".wav", ".wma"]
        self.is_book = [".azw3", ".chm", ".djv", ".djvu", ".epub", ".fb2", ".mobi", ".pdf"]
        self.is_doc = [".accdb", ".doc", ".docm", ".docx", ".dot", ".dotm", ".dotx", ".mdb", ".odp", ".ods", ".odt", ".pdf", ".potm", ".potx", ".ppt", ".pptm", ".pptx", ".rtf", ".xlm", ".xls", ".xlsm", ".xlsx", ".xlt", ".xltm", ".xltx", ".xps"]
        self.is_font = [".eot", ".fon", ".otc", ".otf", ".ttc", ".ttf", ".woff", ".woff2"]
        self.is_image = [".bmp", ".exr", ".gif", ".heic", ".jpeg", ".jpg", ".jxl", ".png", ".psb", ".psd", ".svg", ".tga", ".tiff", ".webp"]
        self.is_source = [".asm", ".awk", ".bas", ".c", ".cc", ".ceylon", ".clj", ".coffee", ".cpp", ".cs", ".d", ".dart", ".elm", ".erl", ".go", ".gradle", ".groovy", ".h", ".hh", ".hpp", ".java", ".jl", ".js", ".jsp", ".jsx", ".kt", ".kts", ".lua", ".nim", ".pas", ".php", ".pl", ".pm", ".py", ".rb", ".rs", ".scala", ".sol", ".swift", ".tcl", ".ts", ".tsx", ".vala", ".vb", ".zig"]
        self.is_video = [".3gp", ".avi", ".flv", ".m4p", ".m4v", ".mkv", ".mov", ".mp4", ".mpeg", ".mpg", ".webm", ".wmv"]
        self.default_file_size_format = ""
        self.us_dates = False
        self.check_for_updates = False

DEFAULT_CONFIG_TEXT = None  # filled below (generated from defaults)

def _make_default_config_text():
    cfg = Config()
    lines = []
    lines.append("no_color = false")
    lines.append("gitignore = false")
    lines.append("hgignore = false")
    lines.append("dockerignore = false")
    for key in ["is_zip_archive","is_archive","is_audio","is_book","is_doc","is_font","is_image","is_source","is_video"]:
        lines.append("%s = [" % key)
        for e in getattr(cfg, key):
            lines.append('    "%s",' % e)
        lines.append("]")
    lines.append('default_file_size_format = ""')
    lines.append("us_dates = false")
    lines.append("check_for_updates = false")
    return "\n".join(lines) + "\n"

# --- minimal TOML parsing (only what config files need) --------------------
class TomlError(Exception):
    def __init__(self, line_no, col, line_text, message, span=1):
        self.line_no = line_no; self.col = col; self.line_text = line_text
        self.message = message; self.span = span
    def format(self):
        return ("TOML parse error at line %d, column %d\n  |\n%d | %s\n  | %s%s\n%s\n" %
                (self.line_no, self.col, self.line_no, self.line_text,
                 " " * (self.col - 1), "^" * max(1, self.span), self.message))

def parse_toml_config(text, cfg):
    """Parse simple key = value / key = [ ... ] TOML into cfg. Raises TomlError."""
    lines = text.split("\n")
    i = 0
    bool_keys = {"no_color", "gitignore", "hgignore", "dockerignore", "us_dates", "check_for_updates"}
    arr_keys = {"is_zip_archive","is_archive","is_audio","is_book","is_doc","is_font","is_image","is_source","is_video"}
    str_keys = {"default_file_size_format"}
    while i < len(lines):
        raw = lines[i]
        line = raw.strip()
        i += 1
        if not line or line.startswith("#"):
            continue
        if line.startswith("["):
            continue  # table headers: unknown, ignore its keys loosely
        m = re.match(r'^([A-Za-z0-9_-]+)\s*=\s*(.*)$', line)
        if not m:
            # mimic toml-rs error: "key with no value, expected `=`"
            # find end of bare key
            km = re.match(r'^([A-Za-z0-9_-]+)', raw)
            col = (len(km.group(1)) + 2) if km else 1
            raise TomlError(i, col, raw, "key with no value, expected `=`")
        key, val = m.group(1), m.group(2).strip()
        # array possibly multiline
        if val.startswith("[") and not val.rstrip().endswith("]"):
            start = i
            while i < len(lines) and "]" not in val:
                val += "\n" + lines[i]; i += 1
        if key in bool_keys:
            if val == "true": setattr(cfg, key, True)
            elif val == "false": setattr(cfg, key, False)
            elif val.startswith('"'):
                inner = val.strip('"')
                col = raw.index(val) + 1
                raise TomlError(i, col, raw, 'invalid type: string "%s", expected a boolean' % inner, span=len(val))
            else:
                col = raw.index(val) + 1 if val in raw else 1
                raise TomlError(i, col, raw, "invalid type: %s, expected a boolean" % val, span=len(val))
        elif key in arr_keys:
            items = re.findall(r'"((?:[^"\\]|\\.)*)"', val)
            if items or val.startswith("["):
                setattr(cfg, key, [x.replace('\\"', '"') for x in items])
        elif key in str_keys:
            sm = re.match(r'^"((?:[^"\\]|\\.)*)"', val) or re.match(r"^'([^']*)'", val)
            if sm: setattr(cfg, key, sm.group(1))
        else:
            # unknown key: ignored by the original (serde default)
            pass
    return cfg

def load_config_file(path, cfg, report_errors=True):
    """Returns True if loaded. Prints TOML errors like the original."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except Exception:
        return False
    try:
        parse_toml_config(text, cfg)
    except TomlError as e:
        if report_errors and not state.no_errors and state.errors_on:
            sys.stderr.write(e.format() + "\n")
        return True  # original continues with defaults either way
    return True

def default_config_path():
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        base = xdg
    else:
        home = os.environ.get("HOME") or os.path.expanduser("~")
        base = os.path.join(home, ".config")
    return os.path.join(base, "fselect", "config.toml")

def exe_dir_config_path():
    try:
        exe = os.path.realpath(sys.argv[0]) if sys.argv and sys.argv[0] else ""
        if exe:
            return os.path.join(os.path.dirname(exe), "config.toml")
    except Exception:
        pass
    return None

def load_default_config():
    """Load config from standard location, next to exe, or create a fresh one."""
    global DEFAULT_CONFIG_TEXT
