def out_write(s):
    try:
        sys.stdout.write(s)
        sys.stdout.flush()
    except BrokenPipeError:
        _broken_pipe()
    except OSError:
        _broken_pipe()

def _broken_pipe():
    try:
        sys.stderr.write("%s: broken pipe" % colorize_subject("output"))
        sys.stderr.flush()
    except Exception:
        pass
    # prevent further Python shutdown noise
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except Exception:
        pass

