        h, mi = int(m.group(1)), int(m.group(2)); sec = int(m.group(3) or 0)
        return (h, mi, sec, "minute" if m.group(3) is None else "second")
    m = re.fullmatch(r'(\d{1,2})', s)
    if m:
        return (int(m.group(1)), 0, 0, "hour")
    m = re.fullmatch(r'(\d{1,2})\s*(am|pm)', s)
    if m:
        h = int(m.group(1))
        return (h, 0, 0, "hour")  # chrono-english quirk: am/pm hour kept as-is here
    return None

def parse_date_interval(s, us_dates=None):
    """Parse a date/time specifier into (start,end) datetimes, or None."""
    if s is None:
        return None
    if us_dates is None:
        us_dates = state.us_dates
    orig = str(s)
    t = orig.strip().lower()
    if not t:
        return None
    today = datetime.date.today()
    # signed integer offset in days
    if re.fullmatch(r'[+-]\d+', t):
        d = today + datetime.timedelta(days=int(t))
        return _interval_for_precision(datetime.datetime(d.year, d.month, d.day), "day")
    # -N days / N days ago / N weeks ago
    m = re.fullmatch(r'-(\d+)\s+(day|days|week|weeks)', t)
    if m:
        n = int(m.group(1)) * (7 if m.group(2).startswith("week") else 1)
        d = today - datetime.timedelta(days=n)
        return _interval_for_precision(datetime.datetime(d.year, d.month, d.day), "day")
    m = re.fullmatch(r'(\d+)\s+(day|days|week|weeks)\s+ago', t)
    if m:
        n = int(m.group(1)) * (7 if m.group(2).startswith("week") else 1)
        d = today - datetime.timedelta(days=n)
        return _interval_for_precision(datetime.datetime(d.year, d.month, d.day), "day")
    # today / yesterday / tomorrow (+ optional time)
    m = re.fullmatch(r'(today|yesterday|tomorrow)(?:\s+(.+))?', t)
    if m:
        off = {"today": 0, "yesterday": -1, "tomorrow": 1}[m.group(1)]
        d = today + datetime.timedelta(days=off)
        base = datetime.datetime(d.year, d.month, d.day)
        if m.group(2):
            tp = _parse_time_part(m.group(2))
            if tp is None: return None
            base = base.replace(hour=tp[0], minute=tp[1], second=tp[2])
            return _interval_for_precision(base, tp[3])
        return _interval_for_precision(base, "day")
    # time alone
    if re.fullmatch(r'\d{1,2}:\d{2}(:\d{2})?', t):
        tp = _parse_time_part(t)
        base = datetime.datetime(today.year, today.month, today.day, tp[0], tp[1], tp[2])
        return _interval_for_precision(base, tp[3])
    # last/next <weekday|month>
    m = re.fullmatch(r'(last|next)\s+(\w+)', t)
    if m:
        word = m.group(2)
        if word == "month":
            y, mo = today.year, today.month
            if m.group(1) == "last":
                mo -= 1
                if mo == 0: mo = 12; y -= 1
            else:
                mo += 1
                if mo == 13: mo = 1; y += 1
            day = min(today.day, [31,29 if y%4==0 and (y%100!=0 or y%400==0) else 28,31,30,31,30,31,31,30,31,30,31][mo-1])
            d = datetime.date(y, mo, day)
            return _interval_for_precision(datetime.datetime(d.year, d.month, d.day), "day")
        if word in WEEKDAYS and (len(word) == 3 or word in ("monday","tuesday","wednesday","thursday","friday","saturday","sunday")):
            target = WEEKDAYS[word]
            cur = today.weekday()
            if m.group(1) == "last":
                delta = (cur - target) % 7
                d = today - datetime.timedelta(days=delta)
            else:
                delta = (target - cur) % 7
                if delta == 0: delta = 7
                d = today + datetime.timedelta(days=delta)
            return _interval_for_precision(datetime.datetime(d.year, d.month, d.day), "day")
        return None
    # bare full weekday name -> next such day (strictly after today)
    if t in ("monday","tuesday","wednesday","thursday","friday","saturday","sunday"):
        target = WEEKDAYS[t]; cur = today.weekday()
        delta = (target - cur) % 7
        if delta == 0: delta = 7
        d = today + datetime.timedelta(days=delta)
        return _interval_for_precision(datetime.datetime(d.year, d.month, d.day), "day")
    # ISO dates
    m = re.fullmatch(r'(\d{4})-(\d{1,2})-(\d{1,2})(?:[ t](\d{1,2})(?::(\d{2}))?(?::(\d{2}))?)?', t)
    if m:
        try:
            base = datetime.datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)),
                                     int(m.group(4) or 0), int(m.group(5) or 0), int(m.group(6) or 0))
        except ValueError:
            return None
        if m.group(4) is None: prec = "day"
        elif m.group(5) is None: prec = "hour"
        elif m.group(6) is None: prec = "minute"
        else: prec = "second"
        return _interval_for_precision(base, prec)
    # D/M/Y or D/M
    m = re.fullmatch(r'(\d{1,2})/(\d{1,2})(?:/(\d{2,4}))?', t)
    if m:
        a, b = int(m.group(1)), int(m.group(2))
        day, month = (b, a) if us_dates else (a, b)
        year = int(m.group(3)) if m.group(3) else today.year
        if year < 100: year += 2000 if year < 70 else 1900
        try:
            base = datetime.datetime(year, month, day)
        except ValueError:
            return None
        return _interval_for_precision(base, "day")
    # textual month forms, optional trailing time
    time_prec = "day"; hh = mm_ = ss = 0
    core = t
    tm = re.search(r'\s+(\d{1,2}:\d{2}(?::\d{2})?|\d{1,2}\s*(?:am|pm))$', t)
    if tm and not re.fullmatch(r'\d{4}-\d{1,2}-\d{1,2}.*', t):
        tp = _parse_time_part(tm.group(1))
        if tp:
            hh, mm_, ss, time_prec = tp; core = t[:tm.start()].strip()
    m = re.fullmatch(r'(\d{1,2})\s+([a-z]+)(?:\s+(\d{2,4}))?', core)
    if m and m.group(2) in MONTHS:
        day = int(m.group(1)); month = MONTHS[m.group(2)]
        year = int(m.group(3)) if m.group(3) else today.year
        try: base = datetime.datetime(year, month, day, hh, mm_, ss)
        except ValueError: return None
        return _interval_for_precision(base, time_prec)
    m = re.fullmatch(r'([a-z]+)\s+(\d{1,2})(?:\s*,\s*(\d{4})|\s+(\d{4}))?', core)
    if m and m.group(1) in MONTHS:
        # "Apr 1 2020" (no comma, with year) is rejected by the original
        if m.group(4) is not None:
            return None
        month = MONTHS[m.group(1)]; day = int(m.group(2))
        year = int(m.group(3)) if m.group(3) else today.year
        try: base = datetime.datetime(year, month, day, hh, mm_, ss)
        except ValueError: return None
        return _interval_for_precision(base, time_prec)
    return None

def parse_datetime_value(s):
    """Parse a field datetime string (YYYY-MM-DD HH:MM:SS etc) to datetime or None."""
    if not s:
        return None
    t = str(s).strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d"):
        try:
            return datetime.datetime.strptime(t, fmt)
        except Exception:
            pass
    iv = parse_date_interval(t)
    if iv:
        return iv[0]
    return None

def fmt_dt(dt):
    return dt.strftime("%Y-%m-%d %H:%M:%S")

def dt_from_ts(ts):
    """Local datetime from unix timestamp seconds (float)."""
    return datetime.datetime.fromtimestamp(ts)

