_statx_ok = None
def birth_time(path, follow):
    global _statx_ok
    if _statx_ok is False:
        return None
    try:
        import ctypes
        libc = ctypes.CDLL("libc.so.6", use_errno=True)
        buf = ctypes.create_string_buffer(256)
        AT_FDCWD = -100
        flags = 0 if follow else 0x100  # AT_SYMLINK_NOFOLLOW
        mask = 0x800  # STATX_BTIME
        p = os.fsencode(path)
        ret = libc.syscall(332, AT_FDCWD, p, flags, mask, buf)
        if ret != 0:
            return None
        mask_out = int.from_bytes(buf.raw[0:4], "little")
        if not (mask_out & 0x800):
            return None
        sec = int.from_bytes(buf.raw[80:88], "little", signed=True)
        nsec = int.from_bytes(buf.raw[88:92], "little")
        if sec == 0 and nsec == 0:
            return None
        return sec + nsec / 1e9
    except Exception:
        _statx_ok = False
        return None

