class FileEntry:
    __slots__ = ("fs_path","root","path_field","name","lstat","meta","meta_follow",
                 "archive","cache","depth","is_archive_entry")
    def __init__(self, fs_path, root, path_field, depth=1, archive=None, name_override=None):
        self.fs_path = fs_path
        self.root = root
        self.path_field = path_field
        self.depth = depth
        self.archive = archive
        self.is_archive_entry = archive is not None
        self.cache = {}
        if name_override is not None:
            self.name = name_override
        else:
            p = path_field if self.is_archive_entry else fs_path
            self.name = p.rstrip("/").split("/")[-1] if p else ""
        self.lstat = None
        self.meta = None
        self.meta_follow = bool(root.symlinks) if root else False
        if not self.is_archive_entry:
            try:
                self.lstat = os.lstat(fs_path)
            except Exception:
                self.lstat = None
            if self.root is not None and self.root.symlinks:
                try:
                    self.meta = os.stat(fs_path)
                except Exception:
                    self.meta = None
            else:
                self.meta = self.lstat
    # helpers
    def lstat_is_dir(self):
        return self.lstat is not None and stat.S_ISDIR(self.lstat.st_mode)
    def lstat_is_symlink(self):
        return self.lstat is not None and stat.S_ISLNK(self.lstat.st_mode)
    def error_subject(self):
        if self.is_archive_entry:
            return self.fs_path
        return self.fs_path
    def read_bytes(self, limit=None):
        if "content" in self.cache and (limit is None or (self.cache.get("content_full"))):
            data = self.cache["content"]
            return data if limit is None else data[:limit]
        try:
            if os.path.isdir(self.fs_path):
                return None
        except Exception:
            pass
        try:
            fd = os.open(self.fs_path, os.O_RDONLY | getattr(os, "O_NONBLOCK", 0))
            try:
                chunks = []
                total = 0
                want = limit if limit is not None else -1
                while want != 0:
                    n = 65536 if want < 0 else min(65536, want)
                    b = os.read(fd, n)
                    if not b:
                        break
                    chunks.append(b); total += len(b)
                    if want > 0:
                        want -= len(b)
                data = b"".join(chunks)
            finally:
                os.close(fd)
        except Exception:
            return None
        if limit is None:
            self.cache["content"] = data; self.cache["content_full"] = True
        return data
    def get(self, canon):
        if canon in self.cache:
            return self.cache[canon]
        val = self._compute(canon)
        self.cache[canon] = val
        return val
    def _compute(self, canon):
        if self.is_archive_entry:
            return self._archive_field(canon)
        return compute_field(self, canon)
    def _archive_field(self, canon):
        a = self.archive
        entry_path = a["entry_path"]
        stem, ext = split_stem_ext(self.name)
        is_dir_e = a.get("is_dir", False)
        if canon == "name": return self.name
        if canon == "filename": return stem
        if canon == "ext": return ext
        if canon == "path": return entry_path
        if canon == "abspath": return entry_path
        if canon == "dir": return entry_path.rsplit("/",1)[0] if "/" in entry_path.rstrip("/") else ""
        if canon == "absdir": return entry_path.rsplit("/",1)[0] if "/" in entry_path.rstrip("/") else ""
        if canon == "size": return str(a["size"])
        if canon == "fsize": return default_format_size(a["size"])
        if canon == "modified":
            dt = a.get("dt")
            return fmt_dt(dt) if dt else ""
        if canon == "is_dir": return b2s(is_dir_e)
        if canon == "is_file": return b2s(not is_dir_e)
        if canon == "is_symlink":
            um = a.get("unix_mode") or 0
            return b2s(stat.S_ISLNK(um)) if um else "false"
        if canon == "mode":
            um = a.get("unix_mode")
            if um:
                return mode_string(um)
            return mode_string(0o100644)
        if canon in ("user_read","user_write","user_exec","user_all","group_read","group_write","group_exec","group_all","other_read","other_write","other_exec","other_all","suid","sgid","is_sticky"):
            um = a.get("unix_mode") or 0o100644
            return perm_field(canon, um)
        if canon == "is_hidden": return b2s(self.name.startswith("."))
        if canon == "is_empty": return b2s(a["size"] == 0)
        if canon in ("is_archive","is_audio","is_book","is_doc","is_font","is_image","is_source","is_video"):
            return b2s(ext_in_list(canon, ext))
        return ""

def perm_field(canon, m):
    bits = {
        "user_read":0o400,"user_write":0o200,"user_exec":0o100,
        "group_read":0o040,"group_write":0o020,"group_exec":0o010,
        "other_read":0o004,"other_write":0o002,"other_exec":0o001,
        "suid":0o4000,"sgid":0o2000,"is_sticky":0o1000,
    }
    if canon == "user_all": return b2s(m & 0o700 == 0o700)
    if canon == "group_all": return b2s(m & 0o070 == 0o070)
    if canon == "other_all": return b2s(m & 0o007 == 0o007)
    return b2s(bool(m & bits[canon]))

def ext_in_list(canon, ext):
    if not ext:
        return False
    lst = getattr(state.config, canon, []) if state.config else []
    e = "." + ext.lower()
    return e in [x.lower() for x in lst]

