            signed = typ == 9
            vals = [int.from_bytes(raw[i*4:(i+1)*4], bo, signed=signed) for i in range(num)]
            return vals[0] if num == 1 else vals
        if typ == 5 or typ == 10:
            signed = typ == 10
            vals = []
            for i in range(num):
                n = int.from_bytes(raw[i*8:i*8+4], bo, signed=signed)
                d = int.from_bytes(raw[i*8+4:i*8+8], bo, signed=signed)
                vals.append((n,d))
            return vals[0] if num == 1 else vals
        if typ == 11 or typ == 12:
            import struct as _st
            fmt = (endian + "f") if typ == 11 else (endian + "d")
            sz = 4 if typ == 11 else 8
            vals = [_st.unpack(fmt, raw[i*sz:(i+1)*sz])[0] for i in range(num)]
            return vals[0] if num == 1 else vals
    except Exception:
        return None
    return raw

def parse_exif(entry, data):
    tags = {}
    gps = {}
    tiff = None; base = 0
    if not data:
        return (tags, gps)
    try:
        if data.startswith(b"\xff\xd8"):
            i = 2
            while i + 4 <= len(data):
                if data[i] != 0xFF: break
                marker = data[i+1]
                seglen = int.from_bytes(data[i+2:i+4], "big")
                if marker == 0xE1 and data[i+4:i+10] == b"Exif\x00\x00":
                    tiff = data[i+10:i+2+seglen]; base = 0; break
                i += 2 + seglen
        elif data[:2] in (b"II", b"MM"):
            tiff = data
        elif data.startswith(b"\x89PNG"):
            i = 8
            while i + 12 <= len(data):
                ln = int.from_bytes(data[i:i+4],"big"); typ = data[i+4:i+8]
                if typ == b"eXIf":
                    tiff = data[i+8:i+8+ln]; break
                i += 12 + ln
        if tiff is None or len(tiff) < 8 or tiff[:2] not in (b"II",b"MM"):
            # WEBP EXIF chunk
            idx = data.find(b"EXIF")
            if idx >= 0:
                tiff = data[idx+8:]
            else:
                return (tags, gps)
        endian = "<" if tiff[:2] == b"II" else ">"
        bo = "little" if endian=="<" else "big"
        if int.from_bytes(tiff[2:4], bo) != 42:
            return (tags, gps)
        off0 = int.from_bytes(tiff[4:8], bo)
        tags.update(parse_ifd(tiff, off0, endian, 0))
        if 34665 in tags and isinstance(tags[34665], int):
            tags.update(parse_ifd(tiff, tags[34665], endian, 0))
        if 34853 in tags and isinstance(tags[34853], int):
            gps = parse_ifd(tiff, tags[34853], endian, 0)
    except Exception:
        pass
    return (tags, gps)

def exif_str(tags, tag):
    v = tags.get(tag)
    if v is None: return ""
    if isinstance(v, str): return v.rstrip("\x00").rstrip()
    if isinstance(v, bytes): return v.decode("utf-8", errors="replace").rstrip("\x00")
    return ""

def exif_rational_str(tags, tag, fraction=False):
    v = tags.get(tag)
    if v is None: return ""
    if isinstance(v, tuple):
        n,d = v
        if d == 0: return ""
        if fraction and n != 0 and abs(n) < abs(d):
            from math import gcd
            g = gcd(n,d)
            return "%d/%d" % (n//g, d//g)
        return rust_float_str(n/d)
    if isinstance(v, (int,float)): return rust_float_str(v)
    return ""

def exif_int_str(tags, *taglist):
    for tag in taglist:
        v = tags.get(tag)
        if v is None: continue
        if isinstance(v, list): v = v[0] if v else None
        if v is None: continue
        if isinstance(v, tuple):
            if v[1] == 0: continue
            return rust_float_str(v[0]/v[1])
        return str(v)
    return ""

def gps_coord(gps, ref_tag, val_tag, neg_refs):
    v = gps.get(val_tag); ref = gps.get(ref_tag)
    if v is None: return ""
    if isinstance(ref, str): ref = ref.rstrip("\x00")
    if isinstance(ref, bytes): ref = ref.decode(errors="replace")
    if not isinstance(v, list) or len(v) < 3: return ""
    parts = []
    for item in v[:3]:
        if isinstance(item, tuple):
            parts.append(item[0]/item[1] if item[1] else 0.0)
        else:
            parts.append(float(item))
    val = parts[0] + parts[1]/60.0 + parts[2]/3600.0
    if isinstance(ref, str) and ref[:1] in neg_refs:
        val = -val
    return rust_float_str(val)

EXIF_ORIENTATION = {1:"row 0 at top and column 0 at left",2:"row 0 at top and column 0 at right",3:"row 0 at bottom and column 0 at right",4:"row 0 at bottom and column 0 at left",5:"row 0 at left and column 0 at top",6:"row 0 at right and column 0 at top",7:"row 0 at right and column 0 at bottom",8:"row 0 at left and column 0 at bottom"}
def exif_enum(tags, tag, mapping, reserved_template):
    v = tags.get(tag)
    if v is None: return ""
    if isinstance(v, list): v = v[0] if v else None
    if v is None: return ""
    return mapping.get(v, reserved_template % v)

def exif_field(entry, canon):
    if "exif" not in entry.cache:
        data = entry.read_bytes(1024*1024)
        entry.cache["exif"] = parse_exif(entry, data or b"")
    tags, gps = entry.cache["exif"]
    if not tags and not gps:
        return ""
    if canon == "exif_datetime":
        s = exif_str(tags, 306)
        return re.sub(r'^(\d{4}):(\d{2}):(\d{2})', r'\1-\2-\3', s) if s else ""
    if canon == "exif_datetime_original":
        s = exif_str(tags, 36867)
        return re.sub(r'^(\d{4}):(\d{2}):(\d{2})', r'\1-\2-\3', s) if s else ""
    if canon == "exif_altitude":
        v = gps.get(6)
        if v is None: return ""
        val = v[0]/v[1] if isinstance(v, tuple) and v[1] else (float(v) if isinstance(v,(int,float)) else None)
        if val is None: return ""
        ref = gps.get(5)
        if isinstance(ref, list): ref = ref[0] if ref else 0
        if ref == 1: val = -val
        return rust_float_str(val)
    if canon == "exif_latitude": return gps_coord(gps, 1, 2, "S")
    if canon == "exif_longitude": return gps_coord(gps, 3, 4, "W")
    if canon == "exif_make": return exif_str(tags, 271)
    if canon == "exif_model": return exif_str(tags, 272)
    if canon == "exif_software": return exif_str(tags, 305)
    if canon == "exif_version":
        v = tags.get(36864)
        if v is None: return ""
        if isinstance(v, (bytes, list)):
            raw = bytes(v) if isinstance(v, list) else v
            s = raw.decode("ascii", errors="replace").strip("\x00")
            if re.fullmatch(r'\d{4}', s):
                major = int(s[:2]); minor = int(s[2:])
                return ("%d.%d" % (major, minor)) if minor % 10 == 0 else ("%d.%02d" % (major, minor))
            return s
        return str(v)
    if canon == "exif_exposure_time": return exif_rational_str(tags, 33434, fraction=True)
    if canon == "exif_aperture": return exif_rational_str(tags, 37378)
    if canon == "exif_shutter_speed": return exif_rational_str(tags, 37377)
    if canon == "exif_f_number": return exif_rational_str(tags, 33437)
    if canon == "exif_iso_speed": return exif_int_str(tags, 34867)
    if canon == "exif_sensitivity": return exif_int_str(tags, 34855)
    if canon == "exif_focal_length": return exif_rational_str(tags, 37386)
    if canon == "exif_lens_make": return exif_str(tags, 42035)
    if canon == "exif_lens_model": return exif_str(tags, 42036)
    if canon == "exif_description": return exif_str(tags, 270)
    if canon == "exif_artist": return exif_str(tags, 315)
    if canon == "exif_copyright": return exif_str(tags, 33432)
    if canon == "exif_orientation":
        return exif_enum(tags, 274, EXIF_ORIENTATION, "[reserved orientation %d]")
    if canon == "exif_flash":
        v = tags.get(37385)
        if v is None: return ""
        if isinstance(v, list): v = v[0]
        parts = ["fired" if v & 1 else "not fired"]
        ret = (v >> 1) & 3
        parts.append({0:"no return light detection function",1:"no return light detection function",2:"return light not detected",3:"return light detected"}[ret])
        mode = (v >> 3) & 3
        parts.append({0:"auto mode 0 (unknown)",1:"forced",2:"suppressed",3:"auto"}[mode])
        if v & 0x20: parts.append("no function present")
        if v & 0x40: parts.append("red-eye reduction")
        return ", ".join(parts)
    if canon == "exif_color_space":
        return exif_enum(tags, 40961, {1:"sRGB",65535:"uncalibrated"}, "[reserved color space %d]")
    if canon == "exif_exposure_program":
        return exif_enum(tags, 34850, {0:"not defined",1:"manual",2:"normal program",3:"aperture priority",4:"shutter priority",5:"creative program",6:"action program",7:"portrait mode",8:"landscape mode"}, "[reserved exposure program %d]")
    if canon == "exif_exposure_bias": return exif_rational_str(tags, 37380)
    if canon == "exif_white_balance":
        return exif_enum(tags, 41987, {0:"auto white balance",1:"manual white balance"}, "[reserved white balance mode %d]")
    if canon == "exif_metering_mode":
        return exif_enum(tags, 37383, {0:"unknown",1:"average",2:"center-weighted average",3:"spot",4:"multi-spot",5:"pattern",6:"partial",255:"other"}, "[reserved metering mode %d]")
    if canon == "exif_scene_type":
        return exif_enum(tags, 41990, {0:"standard",1:"landscape",2:"portrait",3:"night scene"}, "[reserved scene capture type %d]")
    if canon == "exif_contrast":
        return exif_enum(tags, 41992, {0:"normal",1:"soft",2:"hard"}, "[reserved contrast processing %d]")
    if canon == "exif_saturation":
        return exif_enum(tags, 41993, {0:"normal",1:"low saturation",2:"high saturation"}, "[reserved saturation processing %d]")
    if canon == "exif_sharpness":
        return exif_enum(tags, 41994, {0:"normal",1:"soft",2:"hard"}, "[reserved sharpness processing %d]")
    if canon == "exif_body_serial": return exif_str(tags, 42033)
    if canon == "exif_lens_serial": return exif_str(tags, 42037)
    if canon == "exif_user_comment":
        v = tags.get(37500)
        if v is None: return ""
        raw = bytes(v) if isinstance(v, list) else (v if isinstance(v, bytes) else b"")
        if raw.startswith(b"ASCII\x00\x00\x00"):
            return raw[8:].decode("utf-8", errors="replace").rstrip("\x00")
        if raw.startswith(b"UNICODE\x00"):
            try: return raw[8:].decode("utf-16", errors="replace").rstrip("\x00")
            except Exception: return ""
        return ""
    if canon == "exif_image_width": return exif_int_str(tags, 40962, 256)
    if canon == "exif_image_height": return exif_int_str(tags, 40963, 257)
    if canon == "exif_max_aperture": return exif_rational_str(tags, 37381)
    if canon == "exif_digital_zoom": return exif_rational_str(tags, 41988)
    return ""

