# --- content sniffing / parsers ----------------------------------------------
def sniff_mime(data, entry):
    if data is None:
        return ""
    if len(data) == 0:
        return "text/plain"
    # shebang scripts
    if data.startswith(b"#!"):
        first = data.split(b"\n", 1)[0].lower()
        if b"python3" in first: return "text/x-python3"
        if b"python" in first: return "text/x-python"
        if b"perl" in first: return "application/x-perl"
        if b"ruby" in first: return "application/x-ruby"
        if b"node" in first: return "application/javascript"
        return "application/x-shellscript"
    sigs = [
        (b"\x89PNG\r\n\x1a\n", "image/png"),
        (b"\xff\xd8\xff", "image/jpeg"),
        (b"GIF87a", "image/gif"), (b"GIF89a", "image/gif"),
        (b"%PDF-", "application/pdf"),
        (b"PK\x03\x04", "application/zip"), (b"PK\x05\x06", "application/zip"), (b"PK\x07\x08", "application/zip"),
        (b"\x1f\x8b", "application/gzip"),
        (b"BZh", "application/x-bzip2"),
        (b"\xfd7zXZ\x00", "application/x-xz"),
        (b"7z\xbc\xaf\x27\x1c", "application/x-7z-compressed"),
        (b"Rar!\x1a\x07", "application/vnd.rar"),
        (b"ID3", "audio/mpeg"),
        (b"OggS", "audio/ogg"),
        (b"fLaC", "audio/flac"),
        (b"II*\x00", "image/tiff"), (b"MM\x00*", "image/tiff"),
        (b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1", "application/x-ole-storage"),
        (b"\xca\xfe\xba\xbe", "application/x-java"),
        (b"\x00asm", "application/wasm"),
        (b"SQLite format 3\x00", "application/vnd.sqlite3"),
        (b"%!PS", "application/postscript"),
        (b"{\\rtf", "application/rtf"),
        (b"\x7fELF", None),  # handled below (needs more structure)
    ]
    for sig, mime in sigs:
        if mime and data.startswith(sig):
            return mime
    if data.startswith(b"\x7fELF") and len(data) > 16 and data[4] in (1,2) and data[5] in (1,2):
        return "application/x-executable"
    if len(data) >= 262 and data[257:262] == b"ustar":
        return "application/x-tar"
    if len(data) >= 2 and data[0] == 0xFF and (data[1] & 0xE0) == 0xE0 and (data[1] & 0x06) != 0:
        return "audio/mpeg"
    if len(data) >= 12 and data[0:4] == b"RIFF":
        kind = data[8:12]
        if kind == b"WAVE": return "audio/vnd.wave"
        if kind == b"WEBP": return "image/webp"
        if kind == b"AVI ": return "video/x-msvideo"
        return "application/x-riff"
    if len(data) >= 8 and data[4:8] == b"ftyp":
        brand = data[8:12]
        if brand.startswith(b"avif") or brand.startswith(b"avis"): return "image/avif"
        if brand.startswith(b"heic") or brand.startswith(b"heix"): return "image/heic"
        if brand.startswith(b"M4A"): return "audio/mp4"
        return "video/mp4"
    if data.startswith(b"BM") and len(data) >= 26:
        # BMP magic in the mini database needs plausible header fields
        try:
            dib = int.from_bytes(data[14:18], "little")
            if dib >= 12:
                return "image/bmp"
        except Exception:
            pass
    # text-ish formats
    low = data[:512].lstrip().lower()
    if low.startswith(b"<?xml") or low.startswith(b"<svg") and False:
        return "application/xml"
    if low.startswith(b"<?xml"):
        return "application/xml"
    if low.startswith(b"<html") or low.startswith(b"<!doctype html"):
        return "text/html"
    # binary check: NUL bytes or many control chars
    sample = data[:1024]
    if b"\x00" in sample:
        return "application/octet-stream"
    ctrl = sum(1 for b in sample if b < 9 or (9 < b < 32 and b not in (10,13)) or b == 127)
    if sample and ctrl / len(sample) > 0.1:
        return "application/octet-stream"
    return "text/plain"

def image_dimensions(data):
    if not data:
        return None
    try:
        # PNG
        if data.startswith(b"\x89PNG\r\n\x1a\n") and len(data) >= 24:
            return (int.from_bytes(data[16:20],"big"), int.from_bytes(data[20:24],"big"))
        # GIF
        if data[:6] in (b"GIF87a", b"GIF89a") and len(data) >= 10:
            return (int.from_bytes(data[6:8],"little"), int.from_bytes(data[8:10],"little"))
        # BMP
        if data.startswith(b"BM") and len(data) >= 26:
            dib = int.from_bytes(data[14:18],"little")
            if dib == 12:
                return (int.from_bytes(data[18:20],"little"), int.from_bytes(data[20:22],"little"))
            w = int.from_bytes(data[18:22],"little",signed=True)
            h = int.from_bytes(data[22:26],"little",signed=True)
            return (w, abs(h))
        # JPEG
        if data.startswith(b"\xff\xd8"):
            i = 2
            while i + 4 <= len(data):
                if data[i] != 0xFF:
                    i += 1; continue
                marker = data[i+1]
                if marker in (0xD8, 0x01) or 0xD0 <= marker <= 0xD7:
                    i += 2; continue
                seglen = int.from_bytes(data[i+2:i+4],"big")
                if marker in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF) and seglen >= 7:
                    h = int.from_bytes(data[i+5:i+7],"big")
                    w = int.from_bytes(data[i+7:i+9],"big")
                    return (w, h)
                i += 2 + seglen
            return None
        # TIFF
        if data[:2] in (b"II", b"MM") and len(data) >= 8:
            dims = tiff_dimensions(data)
            if dims: return dims
        # WebP
        if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
            kind = data[12:16]
            if kind == b"VP8X" and len(data) >= 30:
                return (int.from_bytes(data[24:27],"little")+1, int.from_bytes(data[27:30],"little")+1)
            if kind == b"VP8 " and len(data) >= 30:
                w = int.from_bytes(data[26:28],"little") & 0x3FFF
                h = int.from_bytes(data[28:30],"little") & 0x3FFF
                return (w, h)
            if kind == b"VP8L" and len(data) >= 25:
                b1,b2,b3,b4 = data[21],data[22],data[23],data[24]
                w = 1 + b1 + ((b2 & 0x3F) << 8)
                h = 1 + ((b2 >> 6) & 3) + (((b3 & 0x3F)) << 2) + 0  # approximation below corrected
                bits = b1 | (b2<<8) | (b3<<16) | (b4<<24)
                w = 1 + (bits & 0x3FFF); h = 1 + ((bits >> 14) & 0x3FFF)
                return (w, h)
        # ICO
        if data[:4] == b"\x00\x00\x01\x00" and len(data) >= 8:
            return (data[6] or 256, data[7] or 256)
        # PSD
        if data.startswith(b"8BPS") and len(data) >= 22:
            return (int.from_bytes(data[18:22],"big"), int.from_bytes(data[14:18],"big"))
        # SVG (text)
        head = data[:2048]
        try:
            text = head.decode("utf-8", errors="replace")
        except Exception:
            text = ""
        if "<svg" in text:
            wm = re.search(r'width\s*=\s*["\']?([\d.]+)', text)
            hm = re.search(r'height\s*=\s*["\']?([\d.]+)', text)
            if wm and hm:
                return (int(float(wm.group(1))), int(float(hm.group(1))))
            vm = re.search(r'viewBox\s*=\s*["\']([\d.\s-]+)["\']', text)
            if vm:
                parts = vm.group(1).split()
                if len(parts) == 4:
                    return (int(float(parts[2])), int(float(parts[3])))
        # MP4
        dims = mp4_dimensions(data)
        if dims: return dims
    except Exception:
        return None
    return None

def tiff_dimensions(data):
    try:
        endian = "<" if data[:2] == b"II" else ">"
        magic = int.from_bytes(data[2:4], "little" if endian=="<" else "big")
        if magic != 42: return None
        off = int.from_bytes(data[4:8], "little" if endian=="<" else "big")
        tags = parse_ifd(data, off, endian, 0)
        w = tags.get(256); h = tags.get(257)
        if isinstance(w, list): w = w[0] if w else None
        if isinstance(h, list): h = h[0] if h else None
        if w and h: return (int(w), int(h))
    except Exception:
        pass
    return None

def mp4_dimensions(data):
    try:
        idx = 0
        # walk top-level boxes looking for moov, then trak/tkhd anywhere
        pos = data.find(b"tkhd")
        if pos < 4:
            return None
        size = int.from_bytes(data[pos-4:pos], "big")
        end = pos - 4 + size
        if size < 32 or end > len(data) + 8:
            # fallback: last 8 bytes after tkhd payload heuristic not reliable
            return None
        w = int.from_bytes(data[end-8:end-4], "big") / 65536.0
        h = int.from_bytes(data[end-4:end], "big") / 65536.0
        if w > 0 and h > 0:
            return (int(w), int(h))
    except Exception:
        pass
    return None

# MP3 -------------------------------------------------------------------------
MP3_GENRES = ["Blues","Classic Rock","Country","Dance","Disco","Funk","Grunge","Hip-Hop","Jazz","Metal","New Age","Oldies","Other","Pop","R&B","Rap","Reggae","Rock","Techno","Industrial","Alternative","Ska","Death Metal","Pranks","Soundtrack","Euro-Techno","Ambient","Trip-Hop","Vocal","Jazz+Funk","Fusion","Trance","Classical","Instrumental","Acid","House","Game","Sound Clip","Gospel","Noise","AlternRock","Bass","Soul","Punk","Space","Meditative","Instrumental Pop","Instrumental Rock","Ethnic","Gothic","Darkwave","Techno-Industrial","Electronic","Pop-Folk","Eurodance","Dream","Southern Rock","Comedy","Cult","Gangsta","Top 40","Christian Rap","Pop/Funk","Jungle","Native American","Cabaret","New Wave","Psychadelic","Rave","Showtunes","Trailer","Lo-Fi","Tribal","Acid Punk","Acid Jazz","Polka","Retro","Musical","Rock & Roll","Hard Rock"]
def parse_mp3(entry, data):
    """Returns dict with duration/bitrate/freq/title/artist/album/year/genre (strings)."""
    res = {}
    if not data:
        return res
    # first audio frame header scan (skip ID3v2 if present)
    offset = 0
    id3v2 = {}
    if data.startswith(b"ID3") and len(data) >= 10:
        size = 0
        for b in data[6:10]:
            size = (size << 7) | (b & 0x7F)
        offset = 10 + size
        version = data[3]
        try:
            id3v2 = parse_id3v2_frames(data[10:10+size], version)
        except Exception:
            id3v2 = {}
    bitrate = freq = None
    frame_start = None
    i = offset
    version_table = {0:"2.5",2:"2",3:"1"}
    while i + 4 <= len(data):
        if data[i] == 0xFF and (data[i+1] & 0xE0) == 0xE0:
            vb = (data[i+1] >> 3) & 0x3
            layer = (data[i+1] >> 1) & 0x3
            bri = (data[i+2] >> 4) & 0xF
            sri = (data[i+2] >> 2) & 0x3
            if vb != 1 and layer == 1 and 0 < bri < 15 and sri < 3:
                v1_bitrates = [32,40,48,56,64,80,96,112,128,160,192,224,256,320]
                v2_bitrates = [8,16,24,32,40,48,56,64,80,96,112,128,144,160]
                bitrate = (v1_bitrates if vb == 3 else v2_bitrates)[bri-1]
                freqs = {3:[44100,48000,32000], 2:[22050,24000,16000], 0:[11025,12000,8000]}
                freq = freqs[vb][sri]
                frame_start = i
                break
        i += 1
    if bitrate:
        res["mp3_bitrate"] = str(bitrate)
        res["mp3_freq"] = str(freq)
        audio_bytes = len(data) - (frame_start or 0)
        # subtract ID3v1 tag if present
        if len(data) >= 128 and data[-128:-125] == b"TAG":
            audio_bytes -= 128
        if bitrate > 0:
            res["duration"] = str(int(audio_bytes * 8 / (bitrate * 1000)))
    # ID3v1 wins in the original behaviour observed; fall back to v2
    tag = {}
    if len(data) >= 128 and data[-128:-125] == b"TAG":
        t = data[-128:]
        def clean(b):
            return b.decode("latin-1", errors="replace").rstrip("\x00").rstrip()
        tag["mp3_title"] = clean(t[3:33]); tag["mp3_artist"] = clean(t[33:63])
        tag["mp3_album"] = clean(t[63:93]); tag["mp3_year"] = clean(t[93:97])
        g = t[127]
        tag["mp3_genre"] = MP3_GENRES[g] if g < len(MP3_GENRES) else ""
    for k, v in tag.items():
        if v != "":
            res[k] = v
    for k, v in id3v2.items():
        if k not in res and v != "":
            res[k] = v
    # genre from v2 may be like "(17)" or "Rap"
    if "mp3_genre" in res:
        gm = re.fullmatch(r'\((\d+)\)', res["mp3_genre"].strip())
        if gm and int(gm.group(1)) < len(MP3_GENRES):
            res["mp3_genre"] = MP3_GENRES[int(gm.group(1))]
    return res

def parse_id3v2_frames(buf, version):
    out = {}
    i = 0
    mapping = {"TIT2":"mp3_title","TPE1":"mp3_artist","TALB":"mp3_album","TYER":"mp3_year","TDRC":"mp3_year","TCON":"mp3_genre"}
    while i + 10 <= len(buf):
        fid = buf[i:i+4].decode("latin-1", errors="replace")
        if not re.fullmatch(r'[A-Z0-9]{4}', fid):
            break
        if version == 4:
            size = 0
            for b in buf[i+4:i+8]: size = (size << 7) | (b & 0x7F)
        else:
            size = int.from_bytes(buf[i+4:i+8], "big")
        payload = buf[i+10:i+10+size]
        if fid in mapping and payload:
            enc = payload[0]
            raw = payload[1:]
            try:
                if enc == 0: txt = raw.decode("latin-1", errors="replace")
                elif enc == 1: txt = raw.decode("utf-16", errors="replace")
                elif enc == 2: txt = raw.decode("utf-16-be", errors="replace")
                else: txt = raw.decode("utf-8", errors="replace")
            except Exception:
                txt = ""
            txt = txt.strip("\x00").strip()
            if mapping[fid] == "mp3_year" and len(txt) >= 4:
                txt = txt[:4]
            out[mapping[fid]] = txt
        i += 10 + size
        if size == 0:
            break
    return out

# EXIF ------------------------------------------------------------------------
def parse_ifd(data, offset, endian, base):
    tags = {}
    try:
        if offset + 2 > len(data): return tags
        cnt = int.from_bytes(data[offset:offset+2], "little" if endian=="<" else "big")
        sizes = {1:1,2:1,3:2,4:4,5:8,6:1,7:1,8:2,9:4,10:8,11:4,12:8}
        for n in range(cnt):
            e = offset + 2 + n*12
            if e + 12 > len(data): break
            tag = int.from_bytes(data[e:e+2], "little" if endian=="<" else "big")
            typ = int.from_bytes(data[e+2:e+4], "little" if endian=="<" else "big")
            num = int.from_bytes(data[e+4:e+8], "little" if endian=="<" else "big")
            sz = sizes.get(typ,1) * num
            if sz <= 4:
                raw = data[e+8:e+8+sz]
            else:
                voff = int.from_bytes(data[e+8:e+12], "little" if endian=="<" else "big")
                raw = data[base+voff:base+voff+sz] if base+voff+sz <= len(data) else b""
            tags[tag] = decode_tiff_value(raw, typ, num, endian)
    except Exception:
        pass
    return tags

def decode_tiff_value(raw, typ, num, endian):
    bo = "little" if endian == "<" else "big"
    try:
        if typ == 2:
            return raw.decode("ascii", errors="replace")
        if typ == 7 or typ == 1 or typ == 6:
            return list(raw) if num != 1 else raw
        if typ == 3 or typ == 8:
            signed = typ == 8
            vals = [int.from_bytes(raw[i*2:(i+1)*2], bo, signed=signed) for i in range(num)]
            return vals[0] if num == 1 else vals
        if typ == 4 or typ == 9:
            signed = typ == 9
            vals = [int.from_bytes(raw[i*4:(i+1)*4], bo, signed=signed) for i in range(num)]
            return vals[0] if num == 1 else vals
        if typ == 5 or typ == 10:
            signed = typ == 10
            vals = []
            for i in range(num):
                n = int.from_bytes(raw[i*8:i*8+4], bo, signed=signed)
                d = int.from_bytes(raw[i*8+4:i*8+8], bo, signed=signed)
                vals.append((n,d))
            return vals[0] if num == 1 else vals
        if typ == 11 or typ == 12:
            import struct as _st
            fmt = (endian + "f") if typ == 11 else (endian + "d")
            sz = 4 if typ == 11 else 8
            vals = [_st.unpack(fmt, raw[i*sz:(i+1)*sz])[0] for i in range(num)]
            return vals[0] if num == 1 else vals
    except Exception:
        return None
    return raw

def parse_exif(entry, data):
    tags = {}
    gps = {}
    tiff = None; base = 0
    if not data:
        return (tags, gps)
    try:
        if data.startswith(b"\xff\xd8"):
            i = 2
            while i + 4 <= len(data):
                if data[i] != 0xFF: break
                marker = data[i+1]
                seglen = int.from_bytes(data[i+2:i+4], "big")
                if marker == 0xE1 and data[i+4:i+10] == b"Exif\x00\x00":
                    tiff = data[i+10:i+2+seglen]; base = 0; break
                i += 2 + seglen
        elif data[:2] in (b"II", b"MM"):
            tiff = data
        elif data.startswith(b"\x89PNG"):
            i = 8
            while i + 12 <= len(data):
                ln = int.from_bytes(data[i:i+4],"big"); typ = data[i+4:i+8]
                if typ == b"eXIf":
                    tiff = data[i+8:i+8+ln]; break
                i += 12 + ln
        if tiff is None or len(tiff) < 8 or tiff[:2] not in (b"II",b"MM"):
            # WEBP EXIF chunk
            idx = data.find(b"EXIF")
            if idx >= 0:
                tiff = data[idx+8:]
            else:
                return (tags, gps)
        endian = "<" if tiff[:2] == b"II" else ">"
        bo = "little" if endian=="<" else "big"
        if int.from_bytes(tiff[2:4], bo) != 42:
            return (tags, gps)
        off0 = int.from_bytes(tiff[4:8], bo)
        tags.update(parse_ifd(tiff, off0, endian, 0))
        if 34665 in tags and isinstance(tags[34665], int):
            tags.update(parse_ifd(tiff, tags[34665], endian, 0))
        if 34853 in tags and isinstance(tags[34853], int):
            gps = parse_ifd(tiff, tags[34853], endian, 0)
    except Exception:
        pass
    return (tags, gps)

def exif_str(tags, tag):
    v = tags.get(tag)
    if v is None: return ""
    if isinstance(v, str): return v.rstrip("\x00").rstrip()
    if isinstance(v, bytes): return v.decode("utf-8", errors="replace").rstrip("\x00")
    return ""

def exif_rational_str(tags, tag, fraction=False):
    v = tags.get(tag)
    if v is None: return ""
    if isinstance(v, tuple):
        n,d = v
        if d == 0: return ""
        if fraction and n != 0 and abs(n) < abs(d):
            from math import gcd
            g = gcd(n,d)
            return "%d/%d" % (n//g, d//g)
        return rust_float_str(n/d)
    if isinstance(v, (int,float)): return rust_float_str(v)
    return ""

def exif_int_str(tags, *taglist):
    for tag in taglist:
        v = tags.get(tag)
        if v is None: continue
        if isinstance(v, list): v = v[0] if v else None
        if v is None: continue
        if isinstance(v, tuple):
            if v[1] == 0: continue
            return rust_float_str(v[0]/v[1])
        return str(v)
    return ""

def gps_coord(gps, ref_tag, val_tag, neg_refs):
    v = gps.get(val_tag); ref = gps.get(ref_tag)
    if v is None: return ""
    if isinstance(ref, str): ref = ref.rstrip("\x00")
    if isinstance(ref, bytes): ref = ref.decode(errors="replace")
    if not isinstance(v, list) or len(v) < 3: return ""
    parts = []
    for item in v[:3]:
        if isinstance(item, tuple):
            parts.append(item[0]/item[1] if item[1] else 0.0)
        else:
            parts.append(float(item))
    val = parts[0] + parts[1]/60.0 + parts[2]/3600.0
    if isinstance(ref, str) and ref[:1] in neg_refs:
        val = -val
    return rust_float_str(val)

EXIF_ORIENTATION = {1:"row 0 at top and column 0 at left",2:"row 0 at top and column 0 at right",3:"row 0 at bottom and column 0 at right",4:"row 0 at bottom and column 0 at left",5:"row 0 at left and column 0 at top",6:"row 0 at right and column 0 at top",7:"row 0 at right and column 0 at bottom",8:"row 0 at left and column 0 at bottom"}
def exif_enum(tags, tag, mapping, reserved_template):
    v = tags.get(tag)
    if v is None: return ""
    if isinstance(v, list): v = v[0] if v else None
    if v is None: return ""
    return mapping.get(v, reserved_template % v)

def exif_field(entry, canon):
    if "exif" not in entry.cache:
        data = entry.read_bytes(1024*1024)
        entry.cache["exif"] = parse_exif(entry, data or b"")
    tags, gps = entry.cache["exif"]
    if not tags and not gps:
        return ""
    if canon == "exif_datetime":
        s = exif_str(tags, 306)
        return re.sub(r'^(\d{4}):(\d{2}):(\d{2})', r'\1-\2-\3', s) if s else ""
    if canon == "exif_datetime_original":
        s = exif_str(tags, 36867)
        return re.sub(r'^(\d{4}):(\d{2}):(\d{2})', r'\1-\2-\3', s) if s else ""
    if canon == "exif_altitude":
        v = gps.get(6)
        if v is None: return ""
        val = v[0]/v[1] if isinstance(v, tuple) and v[1] else (float(v) if isinstance(v,(int,float)) else None)
        if val is None: return ""
        ref = gps.get(5)
        if isinstance(ref, list): ref = ref[0] if ref else 0
        if ref == 1: val = -val
        return rust_float_str(val)
    if canon == "exif_latitude": return gps_coord(gps, 1, 2, "S")
    if canon == "exif_longitude": return gps_coord(gps, 3, 4, "W")
    if canon == "exif_make": return exif_str(tags, 271)
    if canon == "exif_model": return exif_str(tags, 272)
    if canon == "exif_software": return exif_str(tags, 305)
    if canon == "exif_version":
        v = tags.get(36864)
        if v is None: return ""
        if isinstance(v, (bytes, list)):
            raw = bytes(v) if isinstance(v, list) else v
            s = raw.decode("ascii", errors="replace").strip("\x00")
            if re.fullmatch(r'\d{4}', s):
                major = int(s[:2]); minor = int(s[2:])
                return ("%d.%d" % (major, minor)) if minor % 10 == 0 else ("%d.%02d" % (major, minor))
            return s
        return str(v)
    if canon == "exif_exposure_time": return exif_rational_str(tags, 33434, fraction=True)
    if canon == "exif_aperture": return exif_rational_str(tags, 37378)
    if canon == "exif_shutter_speed": return exif_rational_str(tags, 37377)
    if canon == "exif_f_number": return exif_rational_str(tags, 33437)
    if canon == "exif_iso_speed": return exif_int_str(tags, 34867)
    if canon == "exif_sensitivity": return exif_int_str(tags, 34855)
    if canon == "exif_focal_length": return exif_rational_str(tags, 37386)
    if canon == "exif_lens_make": return exif_str(tags, 42035)
    if canon == "exif_lens_model": return exif_str(tags, 42036)
    if canon == "exif_description": return exif_str(tags, 270)
    if canon == "exif_artist": return exif_str(tags, 315)
    if canon == "exif_copyright": return exif_str(tags, 33432)
    if canon == "exif_orientation":
        return exif_enum(tags, 274, EXIF_ORIENTATION, "[reserved orientation %d]")
    if canon == "exif_flash":
        v = tags.get(37385)
        if v is None: return ""
        if isinstance(v, list): v = v[0]
        parts = ["fired" if v & 1 else "not fired"]
        ret = (v >> 1) & 3
        parts.append({0:"no return light detection function",1:"no return light detection function",2:"return light not detected",3:"return light detected"}[ret])
        mode = (v >> 3) & 3
        parts.append({0:"auto mode 0 (unknown)",1:"forced",2:"suppressed",3:"auto"}[mode])
        if v & 0x20: parts.append("no function present")
        if v & 0x40: parts.append("red-eye reduction")
        return ", ".join(parts)
    if canon == "exif_color_space":
        return exif_enum(tags, 40961, {1:"sRGB",65535:"uncalibrated"}, "[reserved color space %d]")
    if canon == "exif_exposure_program":
        return exif_enum(tags, 34850, {0:"not defined",1:"manual",2:"normal program",3:"aperture priority",4:"shutter priority",5:"creative program",6:"action program",7:"portrait mode",8:"landscape mode"}, "[reserved exposure program %d]")
    if canon == "exif_exposure_bias": return exif_rational_str(tags, 37380)
    if canon == "exif_white_balance":
        return exif_enum(tags, 41987, {0:"auto white balance",1:"manual white balance"}, "[reserved white balance mode %d]")
    if canon == "exif_metering_mode":
        return exif_enum(tags, 37383, {0:"unknown",1:"average",2:"center-weighted average",3:"spot",4:"multi-spot",5:"pattern",6:"partial",255:"other"}, "[reserved metering mode %d]")
    if canon == "exif_scene_type":
        return exif_enum(tags, 41990, {0:"standard",1:"landscape",2:"portrait",3:"night scene"}, "[reserved scene capture type %d]")
    if canon == "exif_contrast":
        return exif_enum(tags, 41992, {0:"normal",1:"soft",2:"hard"}, "[reserved contrast processing %d]")
    if canon == "exif_saturation":
        return exif_enum(tags, 41993, {0:"normal",1:"low saturation",2:"high saturation"}, "[reserved saturation processing %d]")
    if canon == "exif_sharpness":
        return exif_enum(tags, 41994, {0:"normal",1:"soft",2:"hard"}, "[reserved sharpness processing %d]")
    if canon == "exif_body_serial": return exif_str(tags, 42033)
    if canon == "exif_lens_serial": return exif_str(tags, 42037)
    if canon == "exif_user_comment":
        v = tags.get(37500)
        if v is None: return ""
        raw = bytes(v) if isinstance(v, list) else (v if isinstance(v, bytes) else b"")
        if raw.startswith(b"ASCII\x00\x00\x00"):
            return raw[8:].decode("utf-8", errors="replace").rstrip("\x00")
        if raw.startswith(b"UNICODE\x00"):
            try: return raw[8:].decode("utf-16", errors="replace").rstrip("\x00")
            except Exception: return ""
        return ""
    if canon == "exif_image_width": return exif_int_str(tags, 40962, 256)
    if canon == "exif_image_height": return exif_int_str(tags, 40963, 257)
    if canon == "exif_max_aperture": return exif_rational_str(tags, 37381)
    if canon == "exif_digital_zoom": return exif_rational_str(tags, 41988)
    return ""

# xattrs / ACL / capabilities / extattrs --------------------------------------
def list_xattrs(path):
    try:
        return os.listxattr(path)  # follows symlinks, like the xattr crate
    except Exception:
        return None

def get_xattr(path, name):
    try:
        return os.getxattr(path, name)
    except Exception:
        return None

def parse_acl_xattr(data):
    """Parse POSIX ACL xattr binary -> (entries list of (tag,perm,id), formatted str)"""
    if not data or len(data) < 4:
        return None
    try:
        entries = []
        i = 4
        while i + 8 <= len(data):
            tag = int.from_bytes(data[i:i+2], "little")
            perm = int.from_bytes(data[i+2:i+4], "little")
            qid = int.from_bytes(data[i+4:i+8], "little")
            entries.append((tag, perm, qid))
            i += 8
        names = {1:"user", 2:"user", 4:"group", 8:"group", 16:"mask", 32:"other"}
        out = []
        for tag, perm, qid in entries:
            tname = names.get(tag, str(tag))
            if tag in (1,4,16,32):
                qual = ""
            elif tag == 2:
                try: qual = pwd.getpwuid(qid).pw_name
                except Exception: qual = str(qid)
            elif tag == 8:
                try: qual = grp.getgrgid(qid).gr_name
                except Exception: qual = str(qid)
            else:
                qual = str(qid)
            pstr = ("r" if perm & 4 else "-") + ("w" if perm & 2 else "-") + ("x" if perm & 1 else "-")
            out.append("%s:%s:%s" % (tname, qual, pstr))
        return (entries, ",".join(out))
    except Exception:
        return None

CAP_NAMES = ["cap_chown","cap_dac_override","cap_dac_read_search","cap_fowner","cap_fsetid","cap_kill","cap_setgid","cap_setuid","cap_setpcap","cap_linux_immutable","cap_net_bind_service","cap_net_broadcast","cap_net_admin","cap_net_raw","cap_ipc_lock","cap_ipc_owner","cap_sys_module","cap_sys_rawio","cap_sys_chroot","cap_sys_ptrace","cap_sys_pacct","cap_sys_admin","cap_sys_boot","cap_sys_nice","cap_sys_resource","cap_sys_time","cap_sys_tty_config","cap_mknod","cap_lease","cap_audit_write","cap_audit_control","cap_setfcap","cap_mac_override","cap_mac_admin","cap_syslog","cap_wake_alarm","cap_block_suspend","cap_audit_read","cap_perfmon","cap_bpf","cap_checkpoint_restore"]
def parse_capabilities(data):
    if not data or len(data) < 20:
        return None
    try:
        magic = int.from_bytes(data[0:4], "little")
        version = (magic >> 24) & 0xFF
        # effective: u32 flags after magic in v2: (magic, effective, permitted[2], inheritable[2])
        effective = int.from_bytes(data[4:8], "little")
        permitted = int.from_bytes(data[8:12], "little") | (int.from_bytes(data[12:16], "little") << 32)
        inheritable = 0
        if len(data) >= 24:
            inheritable = int.from_bytes(data[16:20], "little") | (int.from_bytes(data[20:24], "little") << 32)
        caps = []
        for idx, name in enumerate(CAP_NAMES):
            if permitted & (1 << idx) or inheritable & (1 << idx):
                s = name + "+"
                if effective & 1: s += "e"
                if permitted & (1 << idx): s += "p"
                if inheritable & (1 << idx): s += "i"
                caps.append(s)
        return ",".join(caps)
    except Exception:
        return None

EXTATTR_FLAGS = [
    (0x00000001,"s"),(0x00000002,"u"),(0x00000004,"c"),(0x00000008,"S"),
    (0x00000010,"i"),(0x00000020,"a"),(0x00000040,"d"),(0x00000080,"A"),
