def list_xattrs(path):
    try:
        return os.listxattr(path)  # follows symlinks, like the xattr crate
    except Exception:
        return None

def get_xattr(path, name):
    try:
        return os.getxattr(path, name)
    except Exception:
        return None

def parse_acl_xattr(data):
    """Parse POSIX ACL xattr binary -> (entries list of (tag,perm,id), formatted str)"""
    if not data or len(data) < 4:
        return None
    try:
        entries = []
        i = 4
        while i + 8 <= len(data):
            tag = int.from_bytes(data[i:i+2], "little")
            perm = int.from_bytes(data[i+2:i+4], "little")
            qid = int.from_bytes(data[i+4:i+8], "little")
            entries.append((tag, perm, qid))
            i += 8
        names = {1:"user", 2:"user", 4:"group", 8:"group", 16:"mask", 32:"other"}
        out = []
        for tag, perm, qid in entries:
            tname = names.get(tag, str(tag))
            if tag in (1,4,16,32):
                qual = ""
            elif tag == 2:
                try: qual = pwd.getpwuid(qid).pw_name
                except Exception: qual = str(qid)
            elif tag == 8:
                try: qual = grp.getgrgid(qid).gr_name
                except Exception: qual = str(qid)
            else:
                qual = str(qid)
            pstr = ("r" if perm & 4 else "-") + ("w" if perm & 2 else "-") + ("x" if perm & 1 else "-")
            out.append("%s:%s:%s" % (tname, qual, pstr))
        return (entries, ",".join(out))
    except Exception:
        return None

CAP_NAMES = ["cap_chown","cap_dac_override","cap_dac_read_search","cap_fowner","cap_fsetid","cap_kill","cap_setgid","cap_setuid","cap_setpcap","cap_linux_immutable","cap_net_bind_service","cap_net_broadcast","cap_net_admin","cap_net_raw","cap_ipc_lock","cap_ipc_owner","cap_sys_module","cap_sys_rawio","cap_sys_chroot","cap_sys_ptrace","cap_sys_pacct","cap_sys_admin","cap_sys_boot","cap_sys_nice","cap_sys_resource","cap_sys_time","cap_sys_tty_config","cap_mknod","cap_lease","cap_audit_write","cap_audit_control","cap_setfcap","cap_mac_override","cap_mac_admin","cap_syslog","cap_wake_alarm","cap_block_suspend","cap_audit_read","cap_perfmon","cap_bpf","cap_checkpoint_restore"]
def parse_capabilities(data):
    if not data or len(data) < 20:
        return None
    try:
        magic = int.from_bytes(data[0:4], "little")
        version = (magic >> 24) & 0xFF
        # effective: u32 flags after magic in v2: (magic, effective, permitted[2], inheritable[2])
        effective = int.from_bytes(data[4:8], "little")
        permitted = int.from_bytes(data[8:12], "little") | (int.from_bytes(data[12:16], "little") << 32)
        inheritable = 0
        if len(data) >= 24:
            inheritable = int.from_bytes(data[16:20], "little") | (int.from_bytes(data[20:24], "little") << 32)
        caps = []
        for idx, name in enumerate(CAP_NAMES):
            if permitted & (1 << idx) or inheritable & (1 << idx):
                s = name + "+"
                if effective & 1: s += "e"
                if permitted & (1 << idx): s += "p"
                if inheritable & (1 << idx): s += "i"
                caps.append(s)
        return ",".join(caps)
    except Exception:
        return None

EXTATTR_FLAGS = [
    (0x00000001,"s"),(0x00000002,"u"),(0x00000004,"c"),(0x00000008,"S"),
    (0x00000010,"i"),(0x00000020,"a"),(0x00000040,"d"),(0x00000080,"A"),
    (0x00000800,"E"),(0x00001000,"I"),(0x00004000,"j"),(0x00008000,"t"),
    (0x00010000,"D"),(0x00020000,"T"),(0x00080000,"e"),(0x00100000,"V"),
    (0x00800000,"C"),(0x00200000,"x"),(0x01000000,"N"),(0x02000000,"P"),(0x04000000,"F"),
]
def extattrs_value(path):
    try:
        import fcntl
        fd = os.open(path, os.O_RDONLY | getattr(os, "O_NONBLOCK", 0))
        try:
            buf = fcntl.ioctl(fd, 0x80086601, bytes(4), True)
            flags = int.from_bytes(buf[:4], "little")
        finally:
            os.close(fd)
        return "".join(ch for bit, ch in EXTATTR_FLAGS if flags & bit)
    except Exception:
        return None

