    if canon in ("duration","mp3_bitrate","mp3_freq","mp3_title","mp3_artist","mp3_album","mp3_year","mp3_genre"):
        if "mp3" not in entry.cache:
            data = entry.read_bytes()
            entry.cache["mp3"] = parse_mp3(entry, data or b"")
        return entry.cache["mp3"].get(canon, "")
    if canon.startswith("exif_"):
        return exif_field(entry, canon)
    if canon == "mime":
        try:
            if os.path.isdir(fs):
                return "inode/directory"
        except Exception:
            pass
        data = entry.read_bytes(8192)
        if data is None: return ""
        return sniff_mime(data, entry)
    if canon in ("is_text", "is_binary"):
        mime = entry.get("mime")
        if mime == "": return "false"
        if entry.lstat_is_dir(): return "false"
        is_text = mime.startswith("text/") or mime in ("application/x-shellscript","application/x-perl")
        return b2s(is_text if canon == "is_text" else not is_text)
    if canon == "line_count":
        try:
            if os.path.isdir(fs):
                return ""
        except Exception:
            pass
        data = entry.read_bytes()
        if data is None: return ""
        return str(data.count(b"\n"))
    if canon in ("sha1","sha2_256","sha2_512","sha3_512"):
        try:
            if os.path.isdir(fs):
                return ""
        except Exception:
            pass
        data = entry.read_bytes()
        if data is None: return ""
        h = {"sha1":hashlib.sha1, "sha2_256":hashlib.sha256, "sha2_512":hashlib.sha512, "sha3_512":hashlib.sha3_512}[canon]
        return h(data).hexdigest()
    return ""

