# ---------------------------------------------------------------------------
# Lexer
# ---------------------------------------------------------------------------
class Tok:
    __slots__ = ("type","text")
    def __init__(self, type_, text):
        self.type = type_; self.text = text
    def __repr__(self):
        return "Tok(%s,%r)" % (self.type, self.text)

_OPS = ["===","!==","!=~","!~=","==","!=","<=",">=","=~","~=","<>","=","<",">"]
def _op_at(s, i):
    for op in _OPS:
        if s.startswith(op, i):
            return op
    return None

def lex(s):
    toks = []
    i = 0; n = len(s)
    while i < n:
        c = s[i]
        if c in " \t\r\n":
            i += 1; continue
        if c == ",":
            toks.append(Tok("COMMA", ",")); i += 1; continue
        if c in "({":
            toks.append(Tok("LPAREN", c)); i += 1; continue
        if c in ")}":
            toks.append(Tok("RPAREN", c)); i += 1; continue
        if c in "'\"`":
            j = s.find(c, i+1)
            if j < 0:
                raise ParseError_("Unterminated quoted string: " + s[i+1:])
            toks.append(Tok("STR", s[i+1:j])); i = j+1; continue
        op = _op_at(s, i)
        if op:
            toks.append(Tok("OP", op)); i += len(op); continue
        if c in "=<>!~":
            j = i
            while j < n and s[j] in "=<>!~":
                j += 1
            toks.append(Tok("OP", s[i:j])); i = j; continue
        if c in "+-*/%":
            nxt = s[i+1] if i+1 < n else ""
            if nxt == "" or nxt in " \t\r\n,)}":
                tmap = {"+":"PLUS","-":"MINUS","*":"STAR","/":"SLASH","%":"PERCENT"}
                toks.append(Tok(tmap[c], c)); i += 1; continue
            if c == "*" and nxt in "({":
                toks.append(Tok("STAR", c)); i += 1; continue
        # word
        j = i
        while j < n:
            ch = s[j]
            if ch in " \t\r\n,(){}'\"`":
                break
            if ch in "=<>!~" and _op_at(s, j):
                break
            if ch in "=<>!~":
                break
            j += 1
        if j == i:
            j = i + 1
        toks.append(Tok("WORD", s[i:j])); i = j
    return toks

def strip_outer_quotes(t):
    if len(t) >= 2 and t[0] in "'\"`" and t[-1] == t[0]:
        return t[1:-1]
    return t

def tokens_from_cli_args(args):
    if len(args) == 1:
        return lex(args[0])
    toks = []
    for arg in args:
        low = arg.lower()
        if low.startswith("from "):
            toks.append(Tok("WORD", "from"))
            toks.append(Tok("ROOTSEG", arg[5:]))
            continue
        idx = low.find(" from ")
        if idx >= 0:
            toks.extend(lex(arg[:idx]))
            toks.append(Tok("WORD", "from"))
            toks.append(Tok("ROOTSEG", arg[idx+6:]))
            continue
        if (" " in arg) and (low.startswith(("where ","order ","group ","limit ","offset ","into ")) or
                             " where " in low or " order by " in low or " group by " in low):
            toks.extend(lex(arg))
            continue
        toks.append(Tok("RAW", arg))
    return toks

