class Query:
    def __init__(self):
        self.fields = []
        self.roots = []
        self.where = None
        self.group_by = []
        self.order_by = []
        self.limit = None
        self.offset = None
        self.fmt = "tabs"
        self.raw = ""
        self.has_aggregate = False
        self.star_expanded = False

class Parser:
    def __init__(self, toks, raw=""):
        self.toks = toks
        self.pos = 0
        self.raw = raw
        self.query = Query()
        self.query.raw = raw
    # stream helpers
    def peek(self, expand_raw=True):
        if self.pos >= len(self.toks):
            return None
        t = self.toks[self.pos]
        if t.type == "RAW" and expand_raw:
            # splice lexed tokens for this raw argument
            try:
                sub = lex(t.text)
            except ParseError_:
                raise
            if len(sub) == 0:
                sub = [Tok("WORD", "")]
            self.toks[self.pos:self.pos+1] = sub
            t = self.toks[self.pos]
        return t
    def peek_noexpand(self):
        return self.toks[self.pos] if self.pos < len(self.toks) else None
    def next(self):
        t = self.peek()
        if t is not None:
            self.pos += 1
        return t
    def at_end(self):
        return self.pos >= len(self.toks)
    def peek_word(self):
        t = self.peek()
        if t is not None and t.type == "WORD":
            return t.text.lower()
        return None
    def peek_word_at(self, off):
        # note: does not expand raw beyond current
        idx = self.pos + off
        if idx < len(self.toks) and self.toks[idx].type == "WORD":
            return self.toks[idx].text.lower()
        if idx < len(self.toks) and self.toks[idx].type == "RAW":
            return self.toks[idx].text.lower()
        return None
