        roots_seen = False
        if self.peek_word() == "from":
            q.roots = self.parse_roots(); roots_seen = True
        if self.peek_word() == "where":
            self.next(); q.where = self.parse_condition()
        if self.peek_word() == "group" and self.peek_word_at(1) == "by":
            self.next(); self.next(); q.group_by = self.parse_expr_list()
        if self.peek_word() == "order" and self.peek_word_at(1) == "by":
            self.next(); self.next(); q.order_by = self.parse_order_list()
        if self.peek_word() == "limit":
            self.next(); q.limit = self.parse_limit_value()
        if self.peek_word() == "offset":
            self.next(); q.offset = self.parse_limit_value()
        if self.peek_word() == "into":
            self.next(); q.fmt = self.parse_format()
        if not roots_seen and self.peek_word() == "from":
            q.roots = self.parse_roots(); roots_seen = True
        if not self.at_end():
            raise ParseError_("could not parse tokens at the end of the query")
        q.has_aggregate = any(expr_contains_agg(f) for f in q.fields)
        return q
    def parse_limit_value(self):
        t = self.peek()
        if t is not None and t.type in ("WORD",) and re.fullmatch(r'\d+', t.text):
            self.next(); return int(t.text)
        if t is None:
            raise ParseError_("could not parse tokens at the end of the query")
        # leave token -> final leftover error
        return None
    def parse_format(self):
        t = self.peek()
        if t is None:
            raise ParseError_("Error parsing output format")
        if t.type == "WORD":
            v = t.text.lower()
            if v in ("tabs","lines","list","csv","json","html"):
                self.next(); return v
            raise ParseError_("Unknown output format")
        raise ParseError_("Error parsing output format")
    # fields
    def parse_fields(self):
        fields = []
        while not self.at_end():
            t = self.peek()
            if t is None:
                break
            if t.type == "COMMA":
                self.next(); continue
            if self.is_section_start():
                break
            if self.peek_word() in ("group","order") and self.peek_word_at(1) == "by":
                break
            if t.type == "STAR":
                self.next()
                for canon in ("mode","user","group","size","modified","path"):
                    fields.append(("field", canon, None))
                self.query.star_expanded = True
                continue
            start_pos = self.pos
            expr = self.parse_expression()
            if expr is None:
                if self.pos == start_pos:
                    break
                continue
            fields.append(expr)
        return fields
    def parse_expr_list(self):
        exprs = []
        while not self.at_end():
            t = self.peek()
            if t is not None and t.type == "COMMA":
                self.next(); continue
            if self.is_section_start():
                break
            if self.peek_word() in ("order","group") and self.peek_word_at(1) == "by":
                break
            start = self.pos
            expr = self.parse_expression()
            if expr is None:
                if self.pos == start:
                    break
                continue
            exprs.append(expr)
        return exprs
    def parse_order_list(self):
        items = []
        while not self.at_end():
            t = self.peek()
            if t is not None and t.type == "COMMA":
                self.next(); continue
            if self.is_section_start():
                break
            # numeric position
            if t is not None and t.type == "WORD" and re.fullmatch(r'\d+', t.text):
                posn = int(t.text)
                if posn < 1 or posn > len(self.query.fields):
                    raise ParseError_("Order by field index is out of range")
                self.next()
                node = self.query.fields[posn-1]
            else:
                start = self.pos
                node = self.parse_expression()
                if node is None:
                    if self.pos == start:
                        break
                    continue
            desc = False
            w = self.peek_word()
            if w in ("asc", "desc"):
                desc = w == "desc"; self.next()
            items.append((node, desc))
        return items
    # roots
    def parse_roots(self):
        self.next()  # from
        roots = []
        while True:
            t = self.peek_noexpand()
            if t is None:
                break
            if t.type == "WORD" and t.text.lower() in SECTION_KEYWORDS:
                break
            if t.type == "WORD" and t.text.lower() in ("group","order") and self.peek_word_at(1) == "by":
                break
            if t.type not in ("WORD","STR","RAW","ROOTSEG"):
                break
            if t.type == "ROOTSEG":
                path = strip_outer_quotes(t.text.strip()); self.pos += 1
            elif t.type == "RAW":
                path = strip_outer_quotes(t.text); self.pos += 1
            elif t.type == "STR":
                path = t.text; self.pos += 1
            else:
                path = t.text; self.pos += 1
            root = Root(path)
            self.parse_root_options(root)
            roots.append(root)
            t = self.peek_noexpand()
            if t is not None and t.type == "COMMA":
                self.pos += 1
                # if next is section/end, stop
                nt = self.peek_noexpand()
                if nt is None or (nt.type == "WORD" and nt.text.lower() in SECTION_KEYWORDS):
                    break
                continue
            break
        return roots
    def parse_root_options(self, root):
        while True:
            t = self.peek_noexpand()
            if t is None or t.type in ("COMMA",):
                return
            if t.type == "RAW" and " " in t.text:
                return
            if t.type != "WORD":
                return
            w = t.text.lower()
            if w in SECTION_KEYWORDS or (w in ("group","order") and self.peek_word_at(1) == "by"):
                return
            if w in ("mindepth","maxdepth","depth"):
                self.pos += 1
                nt = self.peek_noexpand()
                if nt is not None and nt.type in ("WORD","RAW") and re.fullmatch(r'\d+', nt.text.strip()):
                    val = int(nt.text.strip()); self.pos += 1
                    if w == "mindepth": root.mindepth = val
                    else: root.maxdepth = val
                    continue
                if nt is None or nt.type == "COMMA" or (nt.type=="WORD" and nt.text.lower() in SECTION_KEYWORDS):
                    raise ParseError_("Error parsing root options")
                return  # leave bad token for final error
            elif w in ("archives","arc"): root.archives = True
            elif w in ("symlinks","sym"): root.symlinks = True
            elif w in ("gitignore","git"): root.gitignore = True
            elif w in ("nogitignore","nogit"): root.gitignore = False
            elif w in ("hgignore","hg"): root.hgignore = True
            elif w in ("nohgignore","nohg"): root.hgignore = False
            elif w in ("dockerignore","docker","dock"): root.dockerignore = True
            elif w in ("nodockerignore","nodocker","nodock"): root.dockerignore = False
            elif w == "dfs": root.dfs = True
            elif w == "bfs": root.dfs = False
            elif w == "regexp": root.regexp = True
            elif w == "as":
                self.pos += 1
                nt = self.peek_noexpand()
                if nt is not None and nt.type in ("WORD","STR","RAW"):
                    root.alias = strip_outer_quotes(nt.text) if nt.type != "STR" else nt.text
                    self.pos += 1
                    continue
                raise ParseError_("Error parsing root options")
            else:
                return
            self.pos += 1
    # expressions
    def parse_expression(self):
        return self.parse_addsub()
    def _arith_word_op(self, w, ops):
        return w in ops
    def parse_addsub(self):
        left = self.parse_muldiv()
        if left is None:
            return None
        while True:
            t = self.peek()
            op = None
            if t is not None and t.type == "PLUS": op = "add"
            elif t is not None and t.type == "MINUS": op = "sub"
            elif t is not None and t.type == "WORD" and t.text.lower() in ("plus","minus"):
                op = "add" if t.text.lower() == "plus" else "sub"
            if not op:
                break
            self.next()
            right = self.parse_muldiv()
            if right is None:
                raise ParseError_("Error parsing expression, expecting string")
            left = ("arith", op, left, right)
        return left
    def parse_muldiv(self):
        left = self.parse_unary()
        if left is None:
            return None
        while True:
            t = self.peek()
            op = None
            if t is not None and t.type == "STAR": op = "mul"
            elif t is not None and t.type == "SLASH": op = "div"
            elif t is not None and t.type == "PERCENT": op = "mod"
            elif t is not None and t.type == "WORD" and t.text.lower() in ("mul","div","mod"):
                op = {"mul":"mul","div":"div","mod":"mod"}[t.text.lower()]
            if not op:
                break
            # A STAR directly after an expression in a field list could be a
            # separate '*' selector only at field boundary; multiplication
            # requires a following operand - check next-next token exists and
            # is not a section keyword.
            self.next()
            right = self.parse_unary()
            if right is None:
                raise ParseError_("Error parsing expression, expecting string")
            left = ("arith", op, left, right)
        return left
    def parse_unary(self):
        t = self.peek()
        if t is not None and t.type == "MINUS":
            self.next()
            inner = self.parse_unary()
            if inner is None:
                raise ParseError_("Error parsing expression, expecting string")
            return ("neg", inner)
        if t is not None and t.type == "PLUS":
            self.next()
            return self.parse_unary()
        return self.parse_atom()
    def try_arith_word(self, text):
        """Parse attached arithmetic chunks like size+1, size-1, 2020/01/02."""
        if re.match(r'\d{4}-\d{1,2}-\d{1,2}', text):
            return None
        if not re.search(r'[+\-*/%]', text[1:] if text[:1] in "+-" else text):
            # still could be like 'a-b' handled below if '-' inside
            if re.search(r'[*/%+]', text) is None and "-" not in text[1:]:
                return None
        # split into operands and ops (not at position 0)
        parts = []
        ops = []
        cur = ""
        for idx, ch in enumerate(text):
            if idx > 0 and ch in "+-*/%":
                parts.append(cur); ops.append(ch); cur = ""
            else:
                cur += ch
        parts.append(cur)
        if len(ops) == 0 or any(p == "" for p in parts):
            return None
        nodes = []
        for p in parts:
            if re.fullmatch(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)', p):
                nodes.append(("lit", p))
            elif canonical_field(p):
                nodes.append(("field", canonical_field(p), None))
            elif p.lower() in FUNC_INFO:
                canon = FUNC_INFO[p.lower()][0]
                nodes.append(("func", canon, []))
            else:
                return None
        # build with precedence (* / % before + -)
        vals = [nodes[0]]; pending = []
        opmap = {"+":"add","-":"sub","*":"mul","/":"div","%":"mod"}
        for op, node in zip(ops, nodes[1:]):
            if op in "*/%":
                vals[-1] = ("arith", opmap[op], vals[-1], node)
            else:
                pending.append(op); vals.append(node)
        expr = vals[0]
        for op, node in zip(pending, vals[1:]):
            expr = ("arith", opmap[op], expr, node)
        return expr
    def parse_atom(self):
        t = self.peek()
        if t is None:
            return None
        if t.type == "LPAREN":
            self.next()
            inner = self.parse_expression()
            nt = self.peek()
            if nt is None or nt.type != "RPAREN":
                raise ParseError_("Unmatched parenthesis")
            self.next()
            return inner
        if t.type == "STR":
            self.next(); return ("lit", t.text)
        if t.type == "STAR":
            self.next(); return ("lit", "*")
        if t.type != "WORD":
            return None
        text = t.text
        low = text.lower()
        if low in NON_ATOM_WORDS:
            return None
        if low in SECTION_KEYWORDS:
            return None
        if low == "group" and self.peek_word_at(1) == "by":
            return None
        # function call or bare function
        if low in FUNC_INFO:
            canon = FUNC_INFO[low][0]
            nt = self.toks[self.pos+1] if self.pos+1 < len(self.toks) else None
            if nt is not None and nt.type == "LPAREN":
                self.next(); self.next()
                args = []
                if canon in AGG_FUNCS:
                    pt = self.peek()
                    if pt is not None and pt.type == "STAR":
                        self.next(); args = [None]
                        # skip to ')'
                        pt = self.peek()
                        if pt is None or pt.type != "RPAREN":
                            raise ParseError_("Unmatched parenthesis")
                        self.next()
                        return ("func", canon, args)
                # check empty args
                pt = self.peek()
                if pt is not None and pt.type == "RPAREN":
                    self.next(); return ("func", canon, [])
                first = True
                while True:
                    if canon in RAW_ARG_FUNCS and first:
                        at = self.peek()
                        if at is not None and at.type in ("WORD","STR"):
                            after = self.toks[self.pos+1] if self.pos+1 < len(self.toks) else None
                            if after is not None and after.type in ("COMMA","RPAREN"):
                                args.append(("lit", at.text)); self.next()
                            else:
                                a = self.parse_expression()
                                if a is None: raise ParseError_("Error parsing expression, expecting string")
                                args.append(a)
                        else:
                            a = self.parse_expression()
                            if a is None: raise ParseError_("Error parsing expression, expecting string")
                            args.append(a)
                    else:
                        a = self.parse_expression()
                        if a is None:
                            raise ParseError_("Error parsing expression, expecting string")
                        args.append(a)
                    first = False
                    pt = self.peek()
                    if pt is not None and pt.type == "COMMA":
                        self.next(); continue
                    break
                pt = self.peek()
                if pt is None or pt.type != "RPAREN":
                    raise ParseError_("Unmatched parenthesis")
                self.next()
                return ("func", canon, args)
            # bare function name = call with no args
            self.next(); return ("func", canon, [])
        # attached arithmetic chunk
        arith = self.try_arith_word(text)
        if arith is not None:
            self.next(); return arith
        # qualified field alias.field
        if text.count(".") == 1 and not text.startswith(".") and not text.endswith("."):
            qual, fname = text.split(".", 1)
            canon = canonical_field(fname)
            if canon:
                self.next(); return ("field", canon, qual)
        canon = canonical_field(text)
        if canon:
            self.next(); return ("field", canon, None)
        self.next(); return ("lit", text)
    # conditions
    def extract_subquery(self):
        """Current token must be '('; consume through matching ')' and parse inner query."""
        t = self.peek()
        if t is None or t.type != "LPAREN":
            raise ParseError_("Error parsing expression, expecting string")
        self.next()
        depth = 1
        start = self.pos
        i = self.pos
        while i < len(self.toks):
            tt = self.toks[i]
            if tt.type == "LPAREN": depth += 1
            elif tt.type == "RPAREN":
                depth -= 1
                if depth == 0:
                    inner = self.toks[start:i]
                    self.pos = i + 1
                    sub = Parser(inner, self.raw)
                    return sub.parse()
            i += 1
        raise ParseError_("Unmatched parenthesis")
    def parse_condition(self):
        return self.parse_or()
    def parse_or(self):
        left = self.parse_and()
        while self.peek_word() == "or":
            self.next()
            right = self.parse_and()
            left = ("or", left, right)
        return left
    def parse_and(self):
        left = self.parse_not()
        while self.peek_word() == "and":
            # 'and' belonging to BETWEEN is consumed inside parse_comparison
            self.next()
            right = self.parse_not()
            left = ("and", left, right)
        return left
    def parse_not(self):
        if self.peek_word() == "not":
            # 'not exists' / 'not <comparison>'
            self.next()
            inner = self.parse_not()
            return ("not", inner)
        return self.parse_comparison()
    def parse_comparison(self):
        t = self.peek()
        if t is None:
            raise ParseError_("Error parsing expression, expecting string")
        if self.peek_word() == "exists":
            self.next()
            subq = self.extract_subquery()
            return ("exists", False, subq)
        if t.type == "LPAREN":
            self.next()
            inner = self.parse_condition()
            nt = self.peek()
            if nt is None or nt.type != "RPAREN":
                raise ParseError_("Unmatched parenthesis")
            self.next()
            # if followed by a comparison operator and inner is a plain
            # expression atom, treat it as the left operand
            if inner[0] == "atom" and self._peek_is_operator():
                return self._comparison_tail(inner[1])
            return inner
        left = self.parse_expression()
        if left is None:
            raise ParseError_("Error parsing expression, expecting string")
        return self._comparison_tail(left)
    def _peek_is_operator(self):
        t = self.peek()
        if t is None: return False
        if t.type == "OP": return True
        if t.type == "WORD":
            w = t.text.lower()
            return w in OPERATOR_WORDS or w in ("in","between","not")
        return False
    def _comparison_tail(self, left):
        t = self.peek()
        if t is None or t.type in ("RPAREN","COMMA"):
            return ("atom", left)
        negate = False
        if t.type == "WORD" and t.text.lower() == "not":
            nxt = self.peek_word_at(1)
            if nxt in ("in","like","between"):
                self.next(); negate = True; t = self.peek()
            else:
                return ("atom", left)
        if t is not None and t.type == "WORD" and t.text.lower() in SECTION_KEYWORDS:
            return ("atom", left)
        if t is not None and t.type == "WORD" and t.text.lower() in ("and","or"):
            return ("atom", left)
        if t is not None and t.type == "WORD" and t.text.lower() in ("group","order") and self.peek_word_at(1) == "by":
            return ("atom", left)
        # operator
        if t is not None and t.type == "OP":
            opraw = t.text
            if opraw not in OPERATOR_WORDS:
                raise ParseError_("Unknown operator: " + opraw)
            op = OPERATOR_WORDS[opraw]; self.next()
            right = self.parse_expression()
            if right is None:
                raise ParseError_("Error parsing expression, expecting string")
            if negate:
                op = {"eq":"ne","like":"notlike","rx":"notrx"}.get(op, op)
            return ("cmp", op, left, right)
        if t is not None and t.type == "WORD":
            w = t.text.lower()
            if w == "between":
                self.next()
                low = self.parse_expression()
                if low is None: raise ParseError_("Error parsing expression, expecting string")
                if self.peek_word() != "and":
                    raise ParseError_("Error parsing expression, expecting string")
                self.next()
                high = self.parse_expression()
                if high is None: raise ParseError_("Error parsing expression, expecting string")
                return ("between", negate, left, low, high)
            if w == "in":
                self.next()
                pt = self.peek()
                if pt is None or pt.type != "LPAREN":
                    raise ParseError_("Error parsing expression, expecting string")
                # subquery?
                # look ahead: 'select' as first word inside parens
                j = self.pos + 1
                is_sub = False
                if j < len(self.toks) and self.toks[j].type == "WORD" and self.toks[j].text.lower() == "select":
                    is_sub = True
                if is_sub:
                    subq = self.extract_subquery()
                    return ("in", negate, left, ("subquery", subq))
                self.next()  # (
                vals = []
                pt = self.peek()
                if pt is not None and pt.type == "RPAREN":
                    self.next(); return ("in", negate, left, ("list", vals))
                while True:
                    v = self.parse_expression()
                    if v is None: raise ParseError_("Error parsing expression, expecting string")
                    vals.append(v)
                    pt = self.peek()
                    if pt is not None and pt.type == "COMMA":
                        self.next(); continue
                    break
                pt = self.peek()
                if pt is None or pt.type != "RPAREN":
                    raise ParseError_("Unmatched parenthesis")
                self.next()
                return ("in", negate, left, ("list", vals))
            if w in OPERATOR_WORDS:
                op = OPERATOR_WORDS[w]; self.next()
                right = self.parse_expression()
                if right is None:
                    raise ParseError_("Error parsing expression, expecting string")
                if negate:
                    op = {"eq":"ne","like":"notlike","rx":"notrx"}.get(op, op)
                return ("cmp", op, left, right)
        return ("atom", left)

def parse_query_tokens(toks, raw=""):
    return Parser(toks, raw).parse()

