class Query:
    def __init__(self):
        self.fields = []
        self.roots = []
        self.where = None
        self.group_by = []
        self.order_by = []
        self.limit = None
        self.offset = None
        self.fmt = "tabs"
        self.raw = ""
        self.has_aggregate = False
        self.star_expanded = False

class Parser:
    def __init__(self, toks, raw=""):
        self.toks = toks
        self.pos = 0
        self.raw = raw
        self.query = Query()
        self.query.raw = raw
    # stream helpers
    def peek(self, expand_raw=True):
        if self.pos >= len(self.toks):
            return None
        t = self.toks[self.pos]
        if t.type == "RAW" and expand_raw:
            # splice lexed tokens for this raw argument
            try:
                sub = lex(t.text)
            except ParseError_:
                raise
            if len(sub) == 0:
                sub = [Tok("WORD", "")]
            self.toks[self.pos:self.pos+1] = sub
            t = self.toks[self.pos]
        return t
    def peek_noexpand(self):
        return self.toks[self.pos] if self.pos < len(self.toks) else None
    def next(self):
        t = self.peek()
        if t is not None:
            self.pos += 1
        return t
    def at_end(self):
        return self.pos >= len(self.toks)
    def peek_word(self):
        t = self.peek()
        if t is not None and t.type == "WORD":
            return t.text.lower()
        return None
    def peek_word_at(self, off):
        # note: does not expand raw beyond current
        idx = self.pos + off
        if idx < len(self.toks) and self.toks[idx].type == "WORD":
            return self.toks[idx].text.lower()
        if idx < len(self.toks) and self.toks[idx].type == "RAW":
            return self.toks[idx].text.lower()
        return None
    def is_section_start(self):
        w = self.peek_word()
        if w in SECTION_KEYWORDS:
            return True
        if w in ("group","order") and self.peek_word_at(1) == "by":
            return True
        if w in ("group","order"):
            # 'group by'/'order by' usually; treat bare group/order carefully:
            # group can be a field; handled by callers
            return False
        return False
    # top-level
    def parse(self):
        q = self.query
        if self.peek_word() == "select":
            self.next()
        q.fields = self.parse_fields()
        if not q.fields:
            raise ParseError_("Error parsing fields, no selector found")
        roots_seen = False
        if self.peek_word() == "from":
            q.roots = self.parse_roots(); roots_seen = True
        if self.peek_word() == "where":
            self.next(); q.where = self.parse_condition()
        if self.peek_word() == "group" and self.peek_word_at(1) == "by":
            self.next(); self.next(); q.group_by = self.parse_expr_list()
        if self.peek_word() == "order" and self.peek_word_at(1) == "by":
            self.next(); self.next(); q.order_by = self.parse_order_list()
        if self.peek_word() == "limit":
            self.next(); q.limit = self.parse_limit_value()
        if self.peek_word() == "offset":
            self.next(); q.offset = self.parse_limit_value()
        if self.peek_word() == "into":
            self.next(); q.fmt = self.parse_format()
        if not roots_seen and self.peek_word() == "from":
            q.roots = self.parse_roots(); roots_seen = True
