            raise ParseError_("Error parsing output format")
        if t.type == "WORD":
            v = t.text.lower()
            if v in ("tabs","lines","list","csv","json","html"):
                self.next(); return v
            raise ParseError_("Unknown output format")
        raise ParseError_("Error parsing output format")
