            if t is None:
                break
            if t.type == "COMMA":
                self.next(); continue
            if self.is_section_start():
                break
            if self.peek_word() in ("group","order") and self.peek_word_at(1) == "by":
                break
            if t.type == "STAR":
                self.next()
                for canon in ("mode","user","group","size","modified","path"):
                    fields.append(("field", canon, None))
                self.query.star_expanded = True
                continue
