    def parse_expr_list(self):
        exprs = []
        while not self.at_end():
            t = self.peek()
            if t is not None and t.type == "COMMA":
                self.next(); continue
            if self.is_section_start():
                break
            if self.peek_word() in ("order","group") and self.peek_word_at(1) == "by":
                break
            start = self.pos
            expr = self.parse_expression()
            if expr is None:
                if self.pos == start:
                    break
                continue
            exprs.append(expr)
        return exprs
    def parse_order_list(self):
        items = []
        while not self.at_end():
            t = self.peek()
            if t is not None and t.type == "COMMA":
                self.next(); continue
            if self.is_section_start():
                break
