            if t is not None and t.type == "WORD" and re.fullmatch(r'\d+', t.text):
                posn = int(t.text)
                if posn < 1 or posn > len(self.query.fields):
                    raise ParseError_("Order by field index is out of range")
                self.next()
                node = self.query.fields[posn-1]
            else:
                start = self.pos
                node = self.parse_expression()
                if node is None:
                    if self.pos == start:
                        break
