                break
            if t.type == "WORD" and t.text.lower() in ("group","order") and self.peek_word_at(1) == "by":
                break
            if t.type not in ("WORD","STR","RAW","ROOTSEG"):
                break
            if t.type == "ROOTSEG":
                path = strip_outer_quotes(t.text.strip()); self.pos += 1
            elif t.type == "RAW":
                path = strip_outer_quotes(t.text); self.pos += 1
            elif t.type == "STR":
                path = t.text; self.pos += 1
            else:
                path = t.text; self.pos += 1
            root = Root(path)
            self.parse_root_options(root)
            roots.append(root)
            t = self.peek_noexpand()
            if t is not None and t.type == "COMMA":
                self.pos += 1
                # if next is section/end, stop
                nt = self.peek_noexpand()
                if nt is None or (nt.type == "WORD" and nt.text.lower() in SECTION_KEYWORDS):
                    break
