    def parse_root_options(self, root):
        while True:
            t = self.peek_noexpand()
            if t is None or t.type in ("COMMA",):
                return
            if t.type == "RAW" and " " in t.text:
                return
            if t.type != "WORD":
                return
            w = t.text.lower()
            if w in SECTION_KEYWORDS or (w in ("group","order") and self.peek_word_at(1) == "by"):
                return
            if w in ("mindepth","maxdepth","depth"):
                self.pos += 1
                nt = self.peek_noexpand()
                if nt is not None and nt.type in ("WORD","RAW") and re.fullmatch(r'\d+', nt.text.strip()):
                    val = int(nt.text.strip()); self.pos += 1
                    if w == "mindepth": root.mindepth = val
                    else: root.maxdepth = val
                    continue
                if nt is None or nt.type == "COMMA" or (nt.type=="WORD" and nt.text.lower() in SECTION_KEYWORDS):
                    raise ParseError_("Error parsing root options")
                return  # leave bad token for final error
            elif w in ("archives","arc"): root.archives = True
            elif w in ("symlinks","sym"): root.symlinks = True
            elif w in ("gitignore","git"): root.gitignore = True
            elif w in ("nogitignore","nogit"): root.gitignore = False
            elif w in ("hgignore","hg"): root.hgignore = True
            elif w in ("nohgignore","nohg"): root.hgignore = False
            elif w in ("dockerignore","docker","dock"): root.dockerignore = True
            elif w in ("nodockerignore","nodocker","nodock"): root.dockerignore = False
            elif w == "dfs": root.dfs = True
            elif w == "bfs": root.dfs = False
            elif w == "regexp": root.regexp = True
            elif w == "as":
                self.pos += 1
                nt = self.peek_noexpand()
                if nt is not None and nt.type in ("WORD","STR","RAW"):
                    root.alias = strip_outer_quotes(nt.text) if nt.type != "STR" else nt.text
                    self.pos += 1
                    continue
                raise ParseError_("Error parsing root options")
            else:
                return
            self.pos += 1
