        parts = []
        ops = []
        cur = ""
        for idx, ch in enumerate(text):
            if idx > 0 and ch in "+-*/%":
                parts.append(cur); ops.append(ch); cur = ""
            else:
                cur += ch
        parts.append(cur)
        if len(ops) == 0 or any(p == "" for p in parts):
            return None
        nodes = []
        for p in parts:
            if re.fullmatch(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)', p):
                nodes.append(("lit", p))
            elif canonical_field(p):
                nodes.append(("field", canonical_field(p), None))
            elif p.lower() in FUNC_INFO:
                canon = FUNC_INFO[p.lower()][0]
                nodes.append(("func", canon, []))
            else:
                return None
