    def extract_subquery(self):
        """Current token must be '('; consume through matching ')' and parse inner query."""
        t = self.peek()
        if t is None or t.type != "LPAREN":
            raise ParseError_("Error parsing expression, expecting string")
        self.next()
        depth = 1
        start = self.pos
        i = self.pos
        while i < len(self.toks):
            tt = self.toks[i]
            if tt.type == "LPAREN": depth += 1
            elif tt.type == "RPAREN":
                depth -= 1
                if depth == 0:
                    inner = self.toks[start:i]
                    self.pos = i + 1
                    sub = Parser(inner, self.raw)
                    return sub.parse()
            i += 1
        raise ParseError_("Unmatched parenthesis")
