    # stream helpers
    def peek(self, expand_raw=True):
        if self.pos >= len(self.toks):
            return None
        t = self.toks[self.pos]
        if t.type == "RAW" and expand_raw:
            # splice lexed tokens for this raw argument
            try:
                sub = lex(t.text)
