            return compute_aggregate(canon, args, ctx)
        argvals = []
        for a in args:
            if a is None:
                argvals.append("*")
            else:
                argvals.append(eval_expr(a, ctx))
        return eval_function(canon, argvals, args, ctx)
    return ""

def compute_aggregate(canon, args, ctx):
    rows = ctx.agg["rows"]
    cache = ctx.agg.setdefault("cache", {})
    key = repr(("func", canon, args))
    if key in cache:
        return cache[key]
    if canon == "count":
        result = str(len(rows))
        cache[key] = result
        return result
    if not args or args[0] is None:
        cache[key] = ""
        return ""
    vals = []
    subctx_entry = ctx.entry
    for e in rows:
        v = eval_expr(args[0], EvalCtx(e, ctx.bindings))
        fv = parse_f64(v)
        if fv is not None:
            vals.append(fv)
    if not vals:
        cache[key] = ""
        return ""
    if canon == "sum": result = rust_float_str(sum(vals))
    elif canon == "avg": result = rust_float_str(sum(vals)/len(vals))
    elif canon == "min": result = rust_float_str(min(vals))
    elif canon == "max": result = rust_float_str(max(vals))
    elif canon in ("var_pop","stddev_pop","var_samp","stddev_samp"):
        mean = sum(vals)/len(vals)
        ss = sum((x-mean)**2 for x in vals)
        if canon == "var_pop": result = rust_float_str(ss/len(vals))
        elif canon == "stddev_pop": result = rust_float_str(math.sqrt(ss/len(vals)))
        elif len(vals) < 2: result = ""
        elif canon == "var_samp": result = rust_float_str(ss/(len(vals)-1))
        else: result = rust_float_str(math.sqrt(ss/(len(vals)-1)))
    else:
        result = ""
    cache[key] = result
    return result

def _arg(vals, i):
    return vals[i] if i < len(vals) else ""

def _int_arg(s):
    v = parse_i64(s)
    if v is not None: return v
    f = parse_f64(s)
    return int(f) if f is not None else 0

def eval_function(canon, vals, argnodes, ctx):
    entry = ctx.entry
    # 0-arg current date/time/user functions and pi
    now = datetime.datetime.now()
    if canon == "current_date": return now.strftime("%Y-%m-%d")
    if canon == "current_time": return now.strftime("%H:%M:%S")
    if canon == "current_timestamp": return fmt_dt(now)
    if canon == "pi": return rust_float_str(math.pi)
    if canon == "current_uid": return str(os.getuid())
    if canon == "current_gid": return str(os.getgid())
    if canon == "current_user":
        try: return pwd.getpwuid(os.getuid()).pw_name
        except Exception: return ""
    if canon == "current_group":
        try: return grp.getgrgid(os.getgid()).gr_name
        except Exception: return ""
    if canon == "rand":
        nums = []
        for v in vals:
            iv = parse_i64(v)
            if iv is None:
                raise EvalError_("Could not parse an argument of RANDOM function: " + v)
            nums.append(iv)
        if len(nums) == 0:
            return str(random.randint(0, 2**63 - 1))
        if len(nums) == 1:
            return str(random.randint(0, nums[0])) if nums[0] > 0 else "0"
        lo, hi = min(nums[0], nums[1]), max(nums[0], nums[1])
        return str(random.randint(lo, hi))
    if canon in ("contains_japanese","contains_hiragana","contains_katakana","contains_kana","contains_kanji","contains_greek"):
        s = _arg(vals, 0)
        def has(ranges):
            return any(any(a <= ord(ch) <= b for a,b in ranges) for ch in s)
        hira = [(0x3040,0x309F)]; kata = [(0x30A0,0x30FF),(0x31F0,0x31FF),(0xFF66,0xFF9D)]
        kanji = [(0x4E00,0x9FFF),(0x3400,0x4DBF)]
        if canon == "contains_hiragana": return b2s(has(hira))
        if canon == "contains_katakana": return b2s(has(kata))
        if canon == "contains_kana": return b2s(has(hira+kata))
        if canon == "contains_kanji": return b2s(has(kanji))
        if canon == "contains_japanese": return b2s(has(hira+kata+kanji))
        return b2s(has([(0x0370,0x03FF),(0x1F00,0x1FFF)]))
    if canon == "contains":
        if entry is None or entry.is_archive_entry:
            return "false"
        data = entry.read_bytes()
        if data is None:
            return "false"
        needle = _arg(vals, 0).encode("utf-8", errors="replace")
        return b2s(needle in data)
    if canon == "coalesce":
        for v in vals:
            if v != "":
                return v
        return ""
    if canon in RAW_ARG_FUNCS or canon == "xattr":
        if not vals:
            return ""
        name = vals[0]
        if entry is None or entry.is_archive_entry:
            return "" if canon == "xattr" else "false"
        if canon == "has_xattr":
            xs = list_xattrs(entry.fs_path)
            return b2s(xs is not None and name in xs)
        if canon == "xattr":
            data = get_xattr(entry.fs_path, name)
            if data is None: return ""
            return data.decode("utf-8", errors="replace").rstrip("\x00")
        if canon == "has_extattr":
            ev = extattrs_value(entry.fs_path)
            return "" if ev is None else b2s(name[:1] in ev if name else False)
        if canon in ("has_acl_entry","acl_entry","has_default_acl_entry","default_acl_entry"):
            xname = "system.posix_acl_access" if "default" not in canon else "system.posix_acl_default"
            data = get_xattr(entry.fs_path, xname)
            if data is None:
                return "false" if canon.startswith("has_") else ""
            parsed = parse_acl_xattr(data)
            if parsed is None:
                return "false" if canon.startswith("has_") else ""
            entries, _fmt = parsed
            perm = find_acl_entry(entries, name)
            if canon.startswith("has_"):
                return b2s(perm is not None)
            if perm is None: return ""
            return ("r" if perm & 4 else "-") + ("w" if perm & 2 else "-") + ("x" if perm & 1 else "-")
        if canon == "has_capability":
            data = get_xattr(entry.fs_path, "security.capability")
            if data is None: return "false"
            caps = parse_capabilities_raw_sets(data)
            nm = name.strip().lower()
            if not nm.startswith("cap_"): nm = "cap_" + nm
            return b2s(nm in caps)
    # string functions
    s0 = _arg(vals, 0)
    if canon == "lower": return s0.lower()
    if canon == "upper": return s0.upper()
    if canon == "initcap":
        out = []
        boundary = True
        for ch in s0:
            if ch.isalpha():
                out.append(ch.upper() if boundary else ch.lower()); boundary = False
            else:
                out.append(ch); boundary = not ch.isdigit()
        return "".join(out)
    if canon == "length": return str(len(s0))
    if canon == "to_base64":
        return base64.b64encode(s0.encode("utf-8")).decode("ascii")
    if canon == "from_base64":
        try:
            return base64.b64decode(s0, validate=False).decode("utf-8")
        except Exception:
            return ""
    if canon == "concat": return "".join(vals)
    if canon == "concat_ws":
        return vals[0].join(vals[1:]) if vals else ""
    if canon == "locate":
        hay, needle = s0, _arg(vals, 1)
        pos = _int_arg(vals[2]) if len(vals) > 2 else 1
        start = max(pos - 1, 0)
        idx = hay.find(needle, start)
        return str(idx + 1 if idx >= 0 else 0)
    if canon == "substr":
        pos = _int_arg(vals[1]) if len(vals) > 1 else 1
        ln = _int_arg(vals[2]) if len(vals) > 2 else None
        chars = s0
        if pos > 0: start = pos - 1
        elif pos == 0: start = 0
        else: start = len(chars) + pos
        if start < 0: start = 0
        if start >= len(chars): return ""
        if ln is None: return chars[start:]
        if ln <= 0: return ""
        return chars[start:start+ln]
    if canon == "replace":
        return s0.replace(_arg(vals,1), _arg(vals,2)) if len(vals) >= 2 else s0
    if canon == "trim": return s0.strip()
    if canon == "ltrim": return s0.lstrip()
    if canon == "rtrim": return s0.rstrip()
    # integer representation functions
    if canon in ("bin","hex","oct"):
        iv = parse_i64(s0)
        if iv is None: return ""
        u = iv & 0xFFFFFFFFFFFFFFFF
        return format(u, {"bin":"b","hex":"x","oct":"o"}[canon])
    # numeric functions
    if canon in ("abs","sqrt","log","ln","exp","power","least","greatest","floor","ceil","round"):
        if canon in ("least","greatest"):
            nums = [parse_f64(v) for v in vals]
            nums = [x for x in nums if x is not None]
            if not nums: return ""
            return rust_float_str(min(nums) if canon == "least" else max(nums))
        fv = parse_f64(s0)
        if fv is None: return ""
        if canon == "abs": return rust_float_str(abs(fv))
        if canon == "sqrt":
            if fv < 0: raise EvalError_("SQRT of a negative number: " + s0)
            return rust_float_str(math.sqrt(fv))
        if canon == "log":
            if fv <= 0: raise EvalError_("LOG of a non-positive number: " + s0)
            base = parse_f64(_arg(vals,1)) if len(vals) > 1 else 10.0
            if base is None or base <= 0 or base == 1: return ""
            return rust_float_str(math.log(fv) / math.log(base))
        if canon == "ln":
            if fv <= 0: raise EvalError_("LN of a non-positive number: " + s0)
            return rust_float_str(math.log(fv))
        if canon == "exp":
            try: r = math.exp(fv)
            except OverflowError: r = math.inf
            if math.isinf(r): raise EvalError_("EXP(%s) overflows to infinity" % s0)
            return rust_float_str(r)
        if canon == "power":
            bv = parse_f64(_arg(vals,1))
            if bv is None: return ""
            try: r = math.pow(fv, bv)
            except OverflowError: r = math.inf
            except ValueError: r = math.nan
            if not math.isfinite(r):
                raise EvalError_("POWER(%s, %s) produces a non-finite result" % (s0, _arg(vals,1)))
            return rust_float_str(r)
        if canon == "floor": return rust_float_str(float(math.floor(fv)))
        if canon == "ceil": return rust_float_str(float(math.ceil(fv)))
        if canon == "round":
            places = _int_arg(vals[1]) if len(vals) > 1 else 0
            factor = 10.0 ** places
            x = fv * factor
            r = math.floor(x + 0.5) if x >= 0 else math.ceil(x - 0.5)
            return rust_float_str(r / factor)
    # datetime functions
    if canon in ("day","month","year","dow","dayname","doy","date_add","date_sub","date_diff","from_unixtime","last_day"):
        if canon == "from_unixtime":
            iv = parse_f64(s0)
            if iv is None: return ""
            try: return fmt_dt(dt_from_ts(iv))
            except Exception: return ""
        dt = parse_datetime_value(s0)
        if dt is None: return ""
        if canon == "day": return str(dt.day)
        if canon == "month": return str(dt.month)
        if canon == "year": return str(dt.year)
        if canon == "dow": return str((dt.weekday() + 1) % 7 + 1)
        if canon == "dayname": return ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"][dt.weekday()]
        if canon == "doy": return str(dt.timetuple().tm_yday)
        if canon == "date_add":
            return fmt_dt(dt + datetime.timedelta(days=_int_arg(_arg(vals,1))))
        if canon == "date_sub":
            return fmt_dt(dt - datetime.timedelta(days=_int_arg(_arg(vals,1))))
        if canon == "date_diff":
            other = parse_datetime_value(_arg(vals,1))
            if other is None: return ""
            return str((dt - other).days)
        if canon == "last_day":
            if dt.month == 12:
                nxt = datetime.datetime(dt.year+1, 1, 1)
            else:
                nxt = datetime.datetime(dt.year, dt.month+1, 1)
            last = nxt - datetime.timedelta(days=1)
            return last.strftime("%Y-%m-%d")
    if canon == "format_size":
        nv = parse_u64(s0)
        if nv is None:
            # values produced by arithmetic may be like '12' (fine) or float
            return ""
        spec = vals[1] if len(vals) > 1 else ""
        return format_size_value(nv, spec)
    if canon == "format_time":
        return format_time_value(s0)
    return ""

def find_acl_entry(entries, spec):
    # spec: type:qualifier ; type in user/u/group/g/mask/m/other/o
    parts = spec.split(":")
    if len(parts) < 1:
        return None
    type_names = {"user":(1,2),"u":(1,2),"group":(4,8),"g":(4,8),"mask":(16,),"m":(16,),"other":(32,),"o":(32,)}
    types = type_names.get(parts[0].lower())
    if types is None:
        return None
    qual = parts[1] if len(parts) > 1 else ""
    for tag, perm, qid in entries:
        if tag not in types:
            continue
        if tag in (1,4,16,32):
            if qual == "":
                return perm
            continue
        # named user/group
        name = ""
        try:
            name = pwd.getpwuid(qid).pw_name if tag == 2 else grp.getgrgid(qid).gr_name
        except Exception:
            name = str(qid)
        if qual == name or qual == str(qid):
            return perm
    return None

def parse_capabilities_raw_sets(data):
    caps = set()
    parsed = parse_capabilities(data)
    if parsed:
        for item in parsed.split(","):
            nm = item.split("+")[0]
            caps.add(nm)
    return caps

# condition evaluation ---------------------------------------------------------
def compare_typed(op, left_node, left_val, right_val):
    lt = expr_type(left_node)
    if op in ("rx","notrx"):
        m = regex_search(right_val, left_val)
        return m if op == "rx" else not m
    if op in ("like","notlike"):
        m = like_match(right_val, left_val)
        return m if op == "like" else not m
    if op == "eeq": return left_val == right_val
    if op == "ene": return left_val != right_val
    if lt == "date":
        if left_val == "":
            return False
        lv = parse_datetime_value(left_val)
        if lv is None:
            return False
        iv = parse_date_interval(right_val)
        if iv is None:
            raise EvalError_("Can't parse datetime: " + right_val)
        start, end = iv
        if op == "eq": return start <= lv <= end
        if op == "ne": return not (start <= lv <= end)
        if op == "gt": return lv > end
        if op == "gte": return lv >= start
        if op == "lt": return lv < start
        if op == "lte": return lv <= end
        return False
    if lt == "bool" and left_val in ("true","false"):
        lb = left_val == "true"
        rb = parse_bool_str(right_val)
        return {"eq": lb == rb, "ne": lb != rb, "gt": (1 if lb else 0) > (1 if rb else 0),
                "gte": (1 if lb else 0) >= (1 if rb else 0), "lt": (1 if lb else 0) < (1 if rb else 0),
                "lte": (1 if lb else 0) <= (1 if rb else 0)}[op]
    if lt in ("int","float") and left_val != "":
        if lt == "int":
            ln_ = parse_number_flex(left_val, integer=True)
            rn_ = parse_number_flex(right_val, integer=True)
        else:
            ln_ = parse_number_flex(left_val)
            rn_ = parse_number_flex(right_val)
        return {"eq": ln_ == rn_, "ne": ln_ != rn_, "gt": ln_ > rn_, "gte": ln_ >= rn_,
                "lt": ln_ < rn_, "lte": ln_ <= rn_}[op]
    # string comparison
    if op in ("eq","ne"):
        if ("*" in right_val or "?" in right_val):
            m = glob_match(right_val, left_val)
            return m if op == "eq" else not m
        return (left_val == right_val) if op == "eq" else (left_val != right_val)
    return {"gt": left_val > right_val, "gte": left_val >= right_val,
            "lt": left_val < right_val, "lte": left_val <= right_val}[op]

def eval_condition(node, ctx):
    kind = node[0]
    if kind == "and":
        left = eval_condition(node[1], ctx)
        if not left:
            return False
        return bool(eval_condition(node[2], ctx))
    if kind == "or":
        left = eval_condition(node[1], ctx)
        if left:
            return True
        return bool(eval_condition(node[2], ctx))
    if kind == "not":
        inner = eval_condition(node[1], ctx)
        if inner is None:
            return False
        return not inner
    if kind == "atom":
        expr = node[1]
        t = expr_type(expr)
        if t != "bool":
            # shorthand is only meaningful for boolean fields/functions;
            # still evaluate to surface errors
            eval_expr(expr, ctx)
            return None
        return eval_expr(expr, ctx) == "true"
    if kind == "cmp":
        _, op, left, right = node
        lv = eval_expr(left, ctx)
        rv = eval_expr(right, ctx)
        return compare_typed(op, left, lv, rv)
    if kind == "between":
        _, negate, left, low, high = node
        lv = eval_expr(left, ctx)
        lo = eval_expr(low, ctx); hi = eval_expr(high, ctx)
        res = compare_typed("gte", left, lv, lo) and compare_typed("lte", left, lv, hi)
        return (not res) if negate else res
    if kind == "in":
        _, negate, left, options = node
        lv = eval_expr(left, ctx)
        if options[0] == "list":
            found = False
            for vexpr in options[1]:
                rv = eval_expr(vexpr, ctx)
                if compare_typed("eq", left, lv, rv):
                    found = True; break
            return (not found) if negate else found
        else:
            values = eval_subquery_values(options[1], ctx)
            found = any(compare_typed("eq", left, lv, v) for v in values)
            return (not found) if negate else found
    if kind == "exists":
        _, negate, subq = node
        rows = eval_subquery_rows(subq, ctx)
        return (len(rows) == 0) if negate else (len(rows) > 0)
    return False

