# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------
class EvalCtx:
    __slots__ = ("entry","bindings","agg")
    def __init__(self, entry, bindings=None, agg=None):
        self.entry = entry
        self.bindings = bindings or {}
        self.agg = agg

def expr_type(node):
    if node[0] == "field":
        return FIELD_INFO[node[1]][1]
    if node[0] in ("arith","neg"):
        return "float"
    if node[0] == "func":
        c = node[1]
        if c in ("length","locate","day","month","year","dow","doy","date_diff","current_uid","current_gid","count"):
            return "int"
        if c in ("abs","power","sqrt","log","ln","exp","least","greatest","pi","floor","ceil","round","rand","min","max","avg","sum","stddev_pop","stddev_samp","var_pop","var_samp"):
            return "float"
        if c in ("contains","contains_japanese","contains_hiragana","contains_katakana","contains_kana","contains_kanji","contains_greek","has_xattr","has_extattr","has_acl_entry","has_default_acl_entry","has_capability"):
            return "bool"
        return "str"
    return "str"

def parse_bool_str(s):
    return str(s).strip().lower() in ("true","1","yes")

def parse_number_flex(s, integer=False):
    t = str(s).strip()
    v = parse_f64(t)
    if v is not None:
        return int(v) if integer else v
    # file size suffix
    m = re.fullmatch(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*([A-Za-z]+)', t)
    if m and m.group(2).lower() in _SIZE_SUFFIX:
        val = float(m.group(1)) * _SIZE_SUFFIX[m.group(2).lower()]
        return int(val) if integer else val
    return 0 if integer else 0.0

def eval_expr(node, ctx):
    # aggregate grouped key shortcut
    if ctx.agg is not None:
        gmap = ctx.agg.get("group_map") or {}
        key = repr(node)
        if key in gmap:
            return gmap[key]
    kind = node[0]
    if kind == "lit":
        return node[1]
    if kind == "field":
        if ctx.agg is not None:
            return ""
        canon, qual = node[1], node[2]
        entry = ctx.entry
        if qual:
            if qual in ctx.bindings:
                entry = ctx.bindings[qual]
            elif entry is not None and entry.root is not None and entry.root.alias:
                # Qualified by a different root alias: empty unless an outer
                # binding exists (bindings checked above).
                if qual != entry.root.alias and ctx.bindings:
                    return ""
                if qual != entry.root.alias and not ctx.bindings:
                    # alias set but qualifier is something else entirety:
                    # original falls back to the entry in simple queries only
                    # when no alias was defined; with an alias defined a
                    # mismatch is empty.
                    return ""
            elif entry is not None and entry.root is not None and not entry.root.alias:
                pass  # no alias defined: qualifier is ignored
        if entry is None:
            return ""
        return entry.get(canon)
    if kind == "neg":
        v = parse_f64_or0(eval_expr(node[1], ctx))
        return rust_float_str(-v)
    if kind == "arith":
        op = node[1]
        a = parse_f64_or0(eval_expr(node[2], ctx))
        b = parse_f64_or0(eval_expr(node[3], ctx))
        if op == "add": r = a + b
        elif op == "sub": r = a - b
        elif op == "mul": r = a * b
        elif op == "div":
            if b == 0: raise EvalError_("Division by zero")
            r = a / b
        elif op == "mod":
            if b == 0: raise EvalError_("Division by zero")
            r = math.fmod(a, b)
        return rust_float_str(r)
    if kind == "func":
        canon, args = node[1], node[2]
        if canon in AGG_FUNCS:
            if ctx.agg is None:
                return ""
            return compute_aggregate(canon, args, ctx)
        argvals = []
        for a in args:
            if a is None:
                argvals.append("*")
            else:
                argvals.append(eval_expr(a, ctx))
        return eval_function(canon, argvals, args, ctx)
    return ""

def compute_aggregate(canon, args, ctx):
    rows = ctx.agg["rows"]
    cache = ctx.agg.setdefault("cache", {})
    key = repr(("func", canon, args))
    if key in cache:
        return cache[key]
    if canon == "count":
        result = str(len(rows))
        cache[key] = result
        return result
    if not args or args[0] is None:
        cache[key] = ""
        return ""
    vals = []
    subctx_entry = ctx.entry
    for e in rows:
        v = eval_expr(args[0], EvalCtx(e, ctx.bindings))
        fv = parse_f64(v)
        if fv is not None:
            vals.append(fv)
    if not vals:
        cache[key] = ""
        return ""
    if canon == "sum": result = rust_float_str(sum(vals))
    elif canon == "avg": result = rust_float_str(sum(vals)/len(vals))
    elif canon == "min": result = rust_float_str(min(vals))
    elif canon == "max": result = rust_float_str(max(vals))
    elif canon in ("var_pop","stddev_pop","var_samp","stddev_samp"):
        mean = sum(vals)/len(vals)
        ss = sum((x-mean)**2 for x in vals)
        if canon == "var_pop": result = rust_float_str(ss/len(vals))
        elif canon == "stddev_pop": result = rust_float_str(math.sqrt(ss/len(vals)))
        elif len(vals) < 2: result = ""
        elif canon == "var_samp": result = rust_float_str(ss/(len(vals)-1))
        else: result = rust_float_str(math.sqrt(ss/(len(vals)-1)))
    else:
        result = ""
    cache[key] = result
    return result

def _arg(vals, i):
    return vals[i] if i < len(vals) else ""

def _int_arg(s):
