def compare_typed(op, left_node, left_val, right_val):
    lt = expr_type(left_node)
    if op in ("rx","notrx"):
        m = regex_search(right_val, left_val)
        return m if op == "rx" else not m
    if op in ("like","notlike"):
        m = like_match(right_val, left_val)
        return m if op == "like" else not m
    if op == "eeq": return left_val == right_val
    if op == "ene": return left_val != right_val
    if lt == "date":
        if left_val == "":
            return False
        lv = parse_datetime_value(left_val)
        if lv is None:
            return False
        iv = parse_date_interval(right_val)
        if iv is None:
            raise EvalError_("Can't parse datetime: " + right_val)
        start, end = iv
        if op == "eq": return start <= lv <= end
        if op == "ne": return not (start <= lv <= end)
        if op == "gt": return lv > end
        if op == "gte": return lv >= start
        if op == "lt": return lv < start
        if op == "lte": return lv <= end
        return False
    if lt == "bool" and left_val in ("true","false"):
        lb = left_val == "true"
        rb = parse_bool_str(right_val)
        return {"eq": lb == rb, "ne": lb != rb, "gt": (1 if lb else 0) > (1 if rb else 0),
                "gte": (1 if lb else 0) >= (1 if rb else 0), "lt": (1 if lb else 0) < (1 if rb else 0),
                "lte": (1 if lb else 0) <= (1 if rb else 0)}[op]
    if lt in ("int","float") and left_val != "":
        if lt == "int":
            ln_ = parse_number_flex(left_val, integer=True)
            rn_ = parse_number_flex(right_val, integer=True)
        else:
            ln_ = parse_number_flex(left_val)
            rn_ = parse_number_flex(right_val)
        return {"eq": ln_ == rn_, "ne": ln_ != rn_, "gt": ln_ > rn_, "gte": ln_ >= rn_,
                "lt": ln_ < rn_, "lte": ln_ <= rn_}[op]
    # string comparison
    if op in ("eq","ne"):
        if ("*" in right_val or "?" in right_val):
            m = glob_match(right_val, left_val)
            return m if op == "eq" else not m
        return (left_val == right_val) if op == "eq" else (left_val != right_val)
    return {"gt": left_val > right_val, "gte": left_val >= right_val,
            "lt": left_val < right_val, "lte": left_val <= right_val}[op]

def eval_condition(node, ctx):
    kind = node[0]
    if kind == "and":
        left = eval_condition(node[1], ctx)
        if not left:
            return False
        return bool(eval_condition(node[2], ctx))
    if kind == "or":
        left = eval_condition(node[1], ctx)
        if left:
            return True
        return bool(eval_condition(node[2], ctx))
    if kind == "not":
        inner = eval_condition(node[1], ctx)
        if inner is None:
            return False
        return not inner
    if kind == "atom":
        expr = node[1]
        t = expr_type(expr)
        if t != "bool":
            # shorthand is only meaningful for boolean fields/functions;
            # still evaluate to surface errors
            eval_expr(expr, ctx)
            return None
        return eval_expr(expr, ctx) == "true"
    if kind == "cmp":
        _, op, left, right = node
        lv = eval_expr(left, ctx)
        rv = eval_expr(right, ctx)
        return compare_typed(op, left, lv, rv)
    if kind == "between":
        _, negate, left, low, high = node
        lv = eval_expr(left, ctx)
        lo = eval_expr(low, ctx); hi = eval_expr(high, ctx)
        res = compare_typed("gte", left, lv, lo) and compare_typed("lte", left, lv, hi)
        return (not res) if negate else res
    if kind == "in":
        _, negate, left, options = node
        lv = eval_expr(left, ctx)
        if options[0] == "list":
            found = False
            for vexpr in options[1]:
                rv = eval_expr(vexpr, ctx)
                if compare_typed("eq", left, lv, rv):
                    found = True; break
            return (not found) if negate else found
        else:
            values = eval_subquery_values(options[1], ctx)
            found = any(compare_typed("eq", left, lv, v) for v in values)
            return (not found) if negate else found
    if kind == "exists":
        _, negate, subq = node
        rows = eval_subquery_rows(subq, ctx)
        return (len(rows) == 0) if negate else (len(rows) > 0)
    return False

