class EvalCtx:
    __slots__ = ("entry","bindings","agg")
    def __init__(self, entry, bindings=None, agg=None):
        self.entry = entry
        self.bindings = bindings or {}
        self.agg = agg

def expr_type(node):
    if node[0] == "field":
        return FIELD_INFO[node[1]][1]
    if node[0] in ("arith","neg"):
        return "float"
    if node[0] == "func":
        c = node[1]
        if c in ("length","locate","day","month","year","dow","doy","date_diff","current_uid","current_gid","count"):
            return "int"
        if c in ("abs","power","sqrt","log","ln","exp","least","greatest","pi","floor","ceil","round","rand","min","max","avg","sum","stddev_pop","stddev_samp","var_pop","var_samp"):
            return "float"
        if c in ("contains","contains_japanese","contains_hiragana","contains_katakana","contains_kana","contains_kanji","contains_greek","has_xattr","has_extattr","has_acl_entry","has_default_acl_entry","has_capability"):
            return "bool"
        return "str"
    return "str"

def parse_bool_str(s):
    return str(s).strip().lower() in ("true","1","yes")

def parse_number_flex(s, integer=False):
    t = str(s).strip()
    v = parse_f64(t)
    if v is not None:
        return int(v) if integer else v
    # file size suffix
    m = re.fullmatch(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*([A-Za-z]+)', t)
    if m and m.group(2).lower() in _SIZE_SUFFIX:
        val = float(m.group(1)) * _SIZE_SUFFIX[m.group(2).lower()]
        return int(val) if integer else val
    return 0 if integer else 0.0

def eval_expr(node, ctx):
    # aggregate grouped key shortcut
    if ctx.agg is not None:
        gmap = ctx.agg.get("group_map") or {}
        key = repr(node)
        if key in gmap:
            return gmap[key]
