    if kind == "lit":
        return node[1]
    if kind == "field":
        if ctx.agg is not None:
            return ""
        canon, qual = node[1], node[2]
        entry = ctx.entry
        if qual:
            if qual in ctx.bindings:
                entry = ctx.bindings[qual]
            elif entry is not None and entry.root is not None and entry.root.alias:
                # Qualified by a different root alias: empty unless an outer
                # binding exists (bindings checked above).
                if qual != entry.root.alias and ctx.bindings:
                    return ""
                if qual != entry.root.alias and not ctx.bindings:
                    # alias set but qualifier is something else entirety:
                    # original falls back to the entry in simple queries only
                    # when no alias was defined; with an alias defined a
                    # mismatch is empty.
                    return ""
