def _glob_seg_regex(pat):
    out = []
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == "*":
            if i + 1 < len(pat) and pat[i+1] == "*":
                out.append(".*"); i += 2
                if i < len(pat) and pat[i] == "/": i += 1
            else:
                out.append("[^/]*"); i += 1
        elif c == "?":
            out.append("[^/]"); i += 1
        elif c == "[":
            j = pat.find("]", i+1)
            if j > i:
                out.append(pat[i:j+1]); i = j+1
            else:
                out.append(re.escape(c)); i += 1
        else:
            out.append(re.escape(c)); i += 1
    return "".join(out)

class IgnoreRule:
    __slots__ = ("pattern","negated","dir_only","anchored","regex")
    def __init__(self, pattern, negated, dir_only, anchored):
        self.pattern = pattern; self.negated = negated; self.dir_only = dir_only; self.anchored = anchored
        self.regex = re.compile("^" + _glob_seg_regex(pattern) + "$")
    def matches(self, rel, is_dir):
        if self.dir_only and not is_dir:
            # a dir-only pattern also matches everything under matching dir
            parts = rel.split("/")
            for k in range(1, len(parts)):
                if self._match_one("/".join(parts[:k])):
                    return True
            return False
        if self._match_one(rel):
            return True
        # pattern matching a parent dir matches descendants
        parts = rel.split("/")
        for k in range(1, len(parts)):
            if self._match_one("/".join(parts[:k])):
                return True
        return False
    def _match_one(self, rel):
        if self.anchored:
            return self.regex.match(rel) is not None
        # match basename or any suffix path
        parts = rel.split("/")
        for k in range(len(parts)):
            if self.regex.match("/".join(parts[k:])):
                return True
        return False

def load_ignore_rules(path):
    rules = []
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            for raw in fh:
                line = raw.rstrip("\n").rstrip("\r")
                if line.strip() == "" or line.lstrip().startswith("#"):
                    continue
                neg = False
                if line.startswith("!"):
                    neg = True; line = line[1:]
                elif line.startswith("\\!"):
                    line = line[1:]
                dir_only = line.endswith("/")
                if dir_only:
                    line = line[:-1]
                anchored = "/" in line
                if line.startswith("/"):
                    line = line[1:]; anchored = True
                if line == "":
                    continue
                try:
                    rules.append(IgnoreRule(line, neg, dir_only, anchored))
                except re.error:
                    pass
    except Exception:
        pass
    return rules

def find_repo_root(start_dir, marker, require_head=False):
    d = os.path.abspath(start_dir)
    while True:
        cand = os.path.join(d, marker)
        if os.path.lexists(cand):
            if require_head:
                if os.path.isfile(cand) or os.path.isfile(os.path.join(cand, "HEAD")):
                    return d
            else:
                return d
        parent = os.path.dirname(d)
        if parent == d:
            return None
        d = parent

class IgnoreEngine:
    def __init__(self, root, root_real):
        cfg = state.config
        self.root = root
        self.root_real = root_real
        self.use_git = root.gitignore if root.gitignore is not None else cfg.gitignore
        self.use_hg = root.hgignore if root.hgignore is not None else cfg.hgignore
        self.use_docker = root.dockerignore if root.dockerignore is not None else cfg.dockerignore
        self.docker_rules = load_ignore_rules(os.path.join(root_real, ".dockerignore")) if self.use_docker else []
        self._rules_cache = {}
    def _stack_rules(self, list_dir_real, kind):
        """Rules [(base_dir, [rules])] applicable to entries directly in list_dir_real."""
        key = (kind, list_dir_real)
        if key in self._rules_cache:
            return self._rules_cache[key]
        result = []
        if kind == "git":
            repo = find_repo_root(list_dir_real, ".git", require_head=True)
            fname = ".gitignore"
        else:
            repo = find_repo_root(list_dir_real, ".hg", require_head=False)
            fname = ".hgignore"
        if repo:
            rel = os.path.relpath(list_dir_real, repo)
            chain = [repo]
            if rel != ".":
                parts = rel.split(os.sep)
                cur = repo
                for p in parts:
                    cur = os.path.join(cur, p); chain.append(cur)
            if kind == "git":
                excl = os.path.join(repo, ".git", "info", "exclude")
                if os.path.isdir(os.path.join(repo, ".git")) and os.path.isfile(excl):
                    result.append((repo, load_ignore_rules(excl)))
            for d in chain:
                f = os.path.join(d, fname)
                if os.path.isfile(f):
                    result.append((d, load_ignore_rules(f)))
        self._rules_cache[key] = result
        return result
    def is_git_repo_dir(self, dir_real):
        cand = os.path.join(dir_real, ".git")
        return os.path.isfile(cand) or os.path.isfile(os.path.join(cand, "HEAD"))
    def is_ignored(self, entry_real, is_dir, list_dir_real):
        decision = False
        any_match = False
        def apply(rules_with_bases):
            nonlocal decision, any_match
            for base, rules in rules_with_bases:
                rel = os.path.relpath(entry_real, base).replace(os.sep, "/")
                if rel.startswith("../"):
                    continue
                for rule in rules:
                    if rule.matches(rel, is_dir):
                        decision = not rule.negated; any_match = True
        if self.use_git:
            apply(self._stack_rules(list_dir_real, "git"))
        if self.use_hg:
            apply(self._stack_rules(list_dir_real, "hg"))
        if self.use_docker and self.docker_rules:
            rel = os.path.relpath(entry_real, self.root_real).replace(os.sep, "/")
            if not rel.startswith("../"):
                for rule in self.docker_rules:
                    if rule.matches(rel, is_dir):
                        decision = not rule.negated; any_match = True
        return decision and any_match

