class Row:
    __slots__ = ("entry","values","bindings","agg")
    def __init__(self, entry, values, bindings=None, agg=None):
        self.entry = entry; self.values = values; self.bindings = bindings or {}; self.agg = agg

def expr_depends_on_file(node):
    if not isinstance(node, tuple):
        return False
    if node[0] == "field":
        return True
    if node[0] == "func":
        if node[1] in ("contains",) or node[1] in RAW_ARG_FUNCS or node[1] in AGG_FUNCS:
            return True
        return any(expr_depends_on_file(a) for a in node[2] if a is not None)
    if node[0] == "arith":
        return expr_depends_on_file(node[2]) or expr_depends_on_file(node[3])
    if node[0] == "neg":
        return expr_depends_on_file(node[1])
    return False

def cond_depends_on_file(node):
    if not isinstance(node, tuple) or node is None:
        return False
    k = node[0]
    if k == "atom": return expr_depends_on_file(node[1])
    if k == "cmp": return expr_depends_on_file(node[2]) or expr_depends_on_file(node[3])
    if k == "between": return any(expr_depends_on_file(x) for x in node[2:5])
    if k == "in":
        if expr_depends_on_file(node[2]): return True
        if node[3][0] == "list": return any(expr_depends_on_file(x) for x in node[3][1])
        return True
    if k == "exists": return True
    if k in ("and","or"): return cond_depends_on_file(node[1]) or cond_depends_on_file(node[2])
    if k == "not": return cond_depends_on_file(node[1])
    return False

def query_depends_on_file(query):
    if query.has_aggregate:
        return True
    if any(expr_depends_on_file(f) for f in query.fields):
        return True
    if query.where is not None and cond_depends_on_file(query.where):
        return True
    if any(expr_depends_on_file(g) for g in query.group_by):
        return True
    if any(expr_depends_on_file(o) for o, d in query.order_by):
        return True
    return False

_subquery_cache = {}

def eval_subquery_rows(subq, ctx):
    bindings = dict(ctx.bindings)
    if ctx.entry is not None and ctx.entry.root is not None and ctx.entry.root.alias:
        bindings[ctx.entry.root.alias] = ctx.entry
    cache_key = None
    # determine whether the subquery references outer bindings by qualifier
    outer_qualifiers = set()
    def collect(node):
        if isinstance(node, tuple):
            if node[0] == "field" and node[2]:
                outer_qualifiers.add(node[2])
            for x in node[1:]:
                collect(x)
        elif isinstance(node, list):
            for x in node: collect(x)
    for f in (subq.fields + subq.group_by + [o for o,d in subq.order_by]):
        collect(f)
    collect(subq.where)
    correlated = bool(outer_qualifiers & set(bindings.keys()))
    if correlated:
        bkey = tuple(sorted((k, v.fs_path if v is not None else "") for k,v in bindings.items() if k in outer_qualifiers))
        cache_key = (id(subq), bkey)
    else:
        cache_key = (id(subq), None)
    if cache_key in _subquery_cache:
        return _subquery_cache[cache_key]
    saved = state.had_io_error
    rows = execute_query(subq, bindings_template=bindings, for_subquery=True)
    state.had_io_error = saved
    _subquery_cache[cache_key] = rows
    return rows

def eval_subquery_values(subq, ctx):
    rows = eval_subquery_rows(subq, ctx)
    out = []
    for r in rows:
        out.append("\t".join(r.values))
    return out

def report_os_error(subject, e):
    if isinstance(e, OSError) and e.errno:
        report(subject, "%s (os error %d)" % (os.strerror(e.errno), e.errno))
    else:
        report(subject, str(e))

def expand_root_path_str(path_str):
    if path_str == "":
        return "."
    if path_str.startswith("~"):
        try:
            return os.path.expanduser(path_str)
        except Exception:
            return path_str
    return path_str

def expand_regexp_root(root):
    expanded = expand_root_path_str(root.path_str)
    pattern = expanded
    # decide whether dynamic segments exist
    segments = pattern.split("/")
    dynamic = [any(ch in seg for ch in "*?[") for seg in segments]
    if not any(dynamic):
        return [root]
    # build regex: segments joined, standalone '*' segment -> [^/]*
    regex_parts = []
    for seg in segments:
        if seg == "*":
            regex_parts.append("[^/]*")
        else:
            regex_parts.append(seg)
    regex_str = "/".join(regex_parts)
    try:
        rx = re.compile(regex_str)
    except re.error:
        report("result", "invalid regex in root path: " + root.path_str, count_exit=False)
        return []
    first_dyn = dynamic.index(True)
    base = "/".join(segments[:first_dyn])
    if base == "":
        base = "/" if pattern.startswith("/") else "."
    candidates = [base]
    for seg in segments[first_dyn:]:
        nxt = []
        is_dyn = any(ch in seg for ch in "*?[")
        for cand in candidates:
            if is_dyn:
                try:
                    with os.scandir(cand) as it:
                        for de in it:
                            nxt.append(os.path.join(cand, de.name))
                except Exception:
                    pass
            else:
                nxt.append(os.path.join(cand, seg))
        candidates = nxt
    out = []
    for cand in candidates:
        if rx.search(cand):
            nr = Root(cand)
            nr.alias = root.alias; nr.mindepth = root.mindepth; nr.maxdepth = root.maxdepth
            nr.archives = root.archives; nr.symlinks = root.symlinks
            nr.gitignore = root.gitignore; nr.hgignore = root.hgignore; nr.dockerignore = root.dockerignore
            nr.dfs = root.dfs; nr.regexp = False
            out.append(nr)
    return out

def execute_query(query, bindings_template=None, for_subquery=False):
    bindings_template = bindings_template or {}
    # constant query: produce a single row without any file access
    if not query_depends_on_file(query):
        ctx = EvalCtx(None, dict(bindings_template))
        try:
            values = [eval_expr(f, ctx) for f in query.fields]
        except EvalError_ as e:
            report(e.subject or "query", e.message)
            return []
        return [Row(None, values)]
    roots = query.roots if query.roots else [Root(".")]
    normal_rows = []
    collected = []  # (entry, bindings, group_key)
    for root in roots:
        actual_roots = expand_regexp_root(root) if root.regexp else [root]
        for aroot in actual_roots:
            _execute_root(query, aroot, bindings_template, normal_rows, collected)
    if query.has_aggregate:
        rows = _build_aggregate_rows(query, collected, bindings_template)
    else:
        rows = normal_rows
    if query.order_by:
        rows = _apply_order(query, rows)
    # offset / limit (limit 0 means no limit in the original)
    off = query.offset or 0
    if off:
        rows = rows[off:]
    if query.limit:
        rows = rows[:query.limit]
    return rows

def _build_aggregate_rows(query, collected, bindings_template):
    rows = []
    if query.group_by:
        groups = {}
        order_keys = []
        for entry, bindings, gkey in collected:
            if gkey not in groups:
                groups[gkey] = []; order_keys.append(gkey)
            groups[gkey].append((entry, bindings))
        for gkey in order_keys:
            members = groups[gkey]
            group_map = {}
            for expr, val in zip(query.group_by, gkey):
                group_map[repr(expr)] = val
            agg = {"rows": [e for e,b in members], "group_map": group_map, "cache": {}}
            bindings = members[0][1]
            ctx = EvalCtx(members[0][0], bindings, agg=agg)
            # aggregate evaluation should not fall back to representative fields
            ctx.entry = None
            try:
                values = [eval_expr(f, ctx) for f in query.fields]
            except EvalError_ as e:
                report(e.subject or members[0][0].error_subject(), e.message)
                continue
            rows.append(Row(members[0][0], values, bindings, agg=agg))
    else:
        entries = [e for e,b,g in collected]
        agg = {"rows": entries, "group_map": {}, "cache": {}}
        bindings = collected[0][1] if collected else dict(bindings_template)
        ctx = EvalCtx(None, bindings, agg=agg)
        try:
            values = [eval_expr(f, ctx) for f in query.fields]
        except EvalError_ as e:
            subj = e.subject or (entries[0].error_subject() if entries else "query")
            report(subj, e.message)
            return []
        rows.append(Row(entries[0] if entries else None, values, bindings, agg=agg))
    return rows

def _apply_order(query, rows):
    decorated = []
    for row in rows:
        keys = []
        for node, desc in query.order_by:
            ctx = EvalCtx(row.entry if row.agg is None else None, row.bindings, agg=row.agg)
            if row.agg is None and row.entry is not None:
                ctx.entry = row.entry
            try:
                keys.append(eval_expr(node, ctx))
            except EvalError_ as e:
                report(e.subject or (row.entry.error_subject() if row.entry else "query"), e.message)
                keys.append("")
        decorated.append((row, keys))
    from functools import cmp_to_key
    def cmp(a, b):
        for idx, (node, desc) in enumerate(query.order_by):
            va = a[1][idx]; vb = b[1][idx]
            t = expr_type(node)
            if t in ("int","float"):
                na = parse_number_flex(va, integer=(t=="int")); nb = parse_number_flex(vb, integer=(t=="int"))
                c = -1 if na < nb else (1 if na > nb else 0)
            elif t == "bool":
                na = 1 if va == "true" else 0; nb = 1 if vb == "true" else 0
                c = -1 if na < nb else (1 if na > nb else 0)
            else:
                c = -1 if va < vb else (1 if va > vb else 0)
            if c:
                return -c if desc else c
        return 0
    decorated.sort(key=cmp_to_key(cmp))
    return [r for r, k in decorated]

