def _execute_root(query, root, bindings_template, normal_rows, collected):
    raw = root.path_str
    expanded = expand_root_path_str(raw)
    # canonicalization errors
    if not os.path.exists(expanded):
        report(raw if raw else expanded, "could not canonicalize path: No such file or directory (os error 2)")
        return
    if not os.path.isdir(expanded):
        report(raw if raw else expanded, "Not a directory (os error 20)")
        return
    root_fs = expanded
    root_real = os.path.realpath(expanded)
    ignore = IgnoreEngine(root, root_real)
    mindepth = root.mindepth or 0
    maxdepth = root.maxdepth or 0
    visited_dirs = set()
    try:
        visited_dirs.add(os.path.realpath(root_fs))
    except Exception:
        pass

    def path_field_for(child_fs):
        base = root_fs
        if base == ".":
            return child_fs[2:] if child_fs.startswith("./") else child_fs
        if base != "/":
            base = base.rstrip("/")
            prefix = base + "/"
            if child_fs.startswith(prefix):
                return child_fs[len(prefix):]
            if child_fs == base:
                return child_fs
            return child_fs
        else:
            return child_fs[1:] if child_fs.startswith("/") else child_fs

    def process_entry(entry, depth, bindings_extra=None):
        """Evaluate where/fields for an entry. Returns (eval_error)."""
        bindings = dict(bindings_template)
        if bindings_extra:
            bindings.update(bindings_extra)
        if root.alias:
            bindings[root.alias] = entry
        ctx = EvalCtx(entry, bindings)
        eval_error = False
        matched = True
        if depth >= mindepth:
            if query.where is not None:
                try:
                    matched = bool(eval_condition(query.where, ctx))
                except EvalError_ as e:
                    report(e.subject or entry.error_subject(), e.message)
                    eval_error = True; matched = False
        else:
            matched = False
        if matched:
            if query.has_aggregate:
                # evaluate aggregate inputs and group keys now (errors prune)
                try:
                    gkey = tuple(eval_expr(g, ctx) for g in query.group_by)
                    for f in query.fields:
                        _eval_agg_inputs(f, ctx)
                except EvalError_ as e:
                    report(e.subject or entry.error_subject(), e.message)
                    return True
                collected.append((entry, bindings, gkey))
            else:
                try:
                    values = [eval_expr(f, ctx) for f in query.fields]
                except EvalError_ as e:
                    report(e.subject or entry.error_subject(), e.message)
                    return True
                normal_rows.append(Row(entry, values, bindings))
        return eval_error

    def process_archive_entries(archive_entry):
        import zipfile
        cfg = state.config
        exts = [x.lower() for x in (cfg.is_zip_archive if cfg else [".zip"])]
        name = archive_entry.name
        stem, ext = split_stem_ext(name)
        if ("." + ext.lower()) not in exts:
            return
        try:
            zf = zipfile.ZipFile(archive_entry.fs_path)
        except Exception:
            return
        try:
            archive_abs = ""
            try:
                archive_abs = os.path.realpath(archive_entry.fs_path)
            except Exception:
                archive_abs = archive_entry.fs_path
            for info in zf.infolist():
                entry_path = info.filename
                is_dir_e = entry_path.endswith("/")
                dt = None
                try:
                    dt = datetime.datetime(*info.date_time)
                except Exception:
                    pass
                unix_mode = (info.external_attr >> 16) & 0xFFFF
                ainfo = {"entry_path": entry_path.rstrip("/") if is_dir_e else entry_path,
                         "size": info.file_size, "dt": dt, "is_dir": is_dir_e,
                         "unix_mode": unix_mode if unix_mode else None,
                         "archive_abs": archive_abs}
                zentry = FileEntry(entry_path.rstrip("/"), root, entry_path.rstrip("/"),
                                   depth=archive_entry.depth, archive=ainfo,
                                   name_override=entry_path.rstrip("/").split("/")[-1])
                process_entry(zentry, archive_entry.depth)
        except Exception:
            pass
        finally:
            try: zf.close()
            except Exception: pass

    def handle_entry(child_fs, de_name, depth):
        """Returns (list_target or None) if this entry should be descended into."""
        entry = FileEntry(child_fs, root, path_field_for(child_fs), depth=depth)
        eval_error = process_entry(entry, depth)
        # archives are processed right after the archive file itself
        if root.archives and not eval_error:
            try:
                if entry.lstat is not None and stat.S_ISREG(entry.lstat.st_mode):
                    process_archive_entries(entry)
            except Exception:
                pass
        if eval_error:
            return None
        is_dir_l = entry.lstat_is_dir()
        list_target = None
        if is_dir_l:
            list_target = child_fs
            if root.symlinks:
                try:
                    rp = os.path.realpath(child_fs)
                    if rp in visited_dirs:
                        list_target = None
                    else:
                        visited_dirs.add(rp)
                except Exception:
                    pass
        elif entry.lstat_is_symlink() and root.symlinks:
            try:
                if os.path.isdir(child_fs):
                    rp = os.path.realpath(child_fs)
                    if rp in visited_dirs:
                        list_target = None
                    else:
                        visited_dirs.add(rp)
                        list_target = rp
            except Exception:
                pass
        if list_target is not None and maxdepth and depth >= maxdepth:
            list_target = None
        return list_target

    def entries_of(list_path):
        try:
            with os.scandir(list_path) as it:
                return list(it)
        except OSError as e:
            report_os_error(list_path, e)
            return None

    def filtered(child_fs, de_name, list_path):
        # ignore filtering (.git special-cased)
        try:
            is_dir_e = False
            lst = os.lstat(child_fs)
            is_dir_e = stat.S_ISDIR(lst.st_mode)
        except Exception:
            return False
        list_real = os.path.realpath(list_path)
        if ignore.use_git and de_name == ".git" and ignore.is_git_repo_dir(list_real):
            return True
        entry_real = os.path.join(list_real, de_name) if not os.path.isabs(child_fs) else os.path.normpath(child_fs)
        # real path without resolving the final symlink for ignore matching
        try:
            entry_real = os.path.join(list_real, de_name)
        except Exception:
            pass
        if ignore.is_ignored(entry_real, is_dir_e, list_real):
            return True
        return False

    if root.dfs:
        def dfs(list_path, child_depth):
            entries = entries_of(list_path)
            if entries is None:
                return
            for de in entries:
                child_fs = os.path.join(list_path, de.name)
                if filtered(child_fs, de.name, list_path):
                    continue
                target = handle_entry(child_fs, de.name, child_depth)
                if target is not None:
                    dfs(target, child_depth + 1)
        dfs(root_fs, 1)
    else:
        queue = deque()
        queue.append((root_fs, 1))
        while queue:
            list_path, child_depth = queue.popleft()
            entries = entries_of(list_path)
            if entries is None:
                continue
            for de in entries:
                child_fs = os.path.join(list_path, de.name)
                if filtered(child_fs, de.name, list_path):
                    continue
                target = handle_entry(child_fs, de.name, child_depth)
                if target is not None:
                    queue.append((target, child_depth + 1))

def _eval_agg_inputs(node, ctx):
    """Evaluate non-aggregate parts of field expressions for one entry.

    Aggregate function arguments are evaluated per entry (to surface errors
    and prune directories), other function/field nodes are simply evaluated.
    """
    if not isinstance(node, tuple):
        return
    if node[0] == "func" and node[1] in AGG_FUNCS:
        for a in node[2]:
            if a is not None:
                eval_expr(a, ctx)
        return
    if node[0] == "func":
        eval_expr(node, ctx)
        return
