    maxdepth = root.maxdepth or 0
    visited_dirs = set()
    try:
        visited_dirs.add(os.path.realpath(root_fs))
    except Exception:
        pass

    def path_field_for(child_fs):
        base = root_fs
        if base == ".":
            return child_fs[2:] if child_fs.startswith("./") else child_fs
        if base != "/":
            base = base.rstrip("/")
            prefix = base + "/"
            if child_fs.startswith(prefix):
                return child_fs[len(prefix):]
            if child_fs == base:
                return child_fs
            return child_fs
        else:
            return child_fs[1:] if child_fs.startswith("/") else child_fs

    def process_entry(entry, depth, bindings_extra=None):
        """Evaluate where/fields for an entry. Returns (eval_error)."""
        bindings = dict(bindings_template)
        if bindings_extra:
            bindings.update(bindings_extra)
        if root.alias:
            bindings[root.alias] = entry
        ctx = EvalCtx(entry, bindings)
        eval_error = False
        matched = True
        if depth >= mindepth:
            if query.where is not None:
                try:
                    matched = bool(eval_condition(query.where, ctx))
                except EvalError_ as e:
                    report(e.subject or entry.error_subject(), e.message)
                    eval_error = True; matched = False
        else:
            matched = False
        if matched:
            if query.has_aggregate:
                # evaluate aggregate inputs and group keys now (errors prune)
                try:
                    gkey = tuple(eval_expr(g, ctx) for g in query.group_by)
                    for f in query.fields:
                        _eval_agg_inputs(f, ctx)
                except EvalError_ as e:
                    report(e.subject or entry.error_subject(), e.message)
                    return True
                collected.append((entry, bindings, gkey))
            else:
                try:
                    values = [eval_expr(f, ctx) for f in query.fields]
                except EvalError_ as e:
                    report(e.subject or entry.error_subject(), e.message)
                    return True
                normal_rows.append(Row(entry, values, bindings))
        return eval_error

    def process_archive_entries(archive_entry):
        import zipfile
        cfg = state.config
        exts = [x.lower() for x in (cfg.is_zip_archive if cfg else [".zip"])]
        name = archive_entry.name
        stem, ext = split_stem_ext(name)
        if ("." + ext.lower()) not in exts:
            return
        try:
            zf = zipfile.ZipFile(archive_entry.fs_path)
        except Exception:
            return
        try:
            archive_abs = ""
