                archive_abs = os.path.realpath(archive_entry.fs_path)
            except Exception:
                archive_abs = archive_entry.fs_path
            for info in zf.infolist():
                entry_path = info.filename
                is_dir_e = entry_path.endswith("/")
                dt = None
                try:
                    dt = datetime.datetime(*info.date_time)
                except Exception:
                    pass
                unix_mode = (info.external_attr >> 16) & 0xFFFF
                ainfo = {"entry_path": entry_path.rstrip("/") if is_dir_e else entry_path,
                         "size": info.file_size, "dt": dt, "is_dir": is_dir_e,
                         "unix_mode": unix_mode if unix_mode else None,
                         "archive_abs": archive_abs}
