        list_target = None
        if is_dir_l:
            list_target = child_fs
            if root.symlinks:
                try:
                    rp = os.path.realpath(child_fs)
                    if rp in visited_dirs:
                        list_target = None
                    else:
                        visited_dirs.add(rp)
                except Exception:
                    pass
        elif entry.lstat_is_symlink() and root.symlinks:
            try:
                if os.path.isdir(child_fs):
                    rp = os.path.realpath(child_fs)
                    if rp in visited_dirs:
                        list_target = None
                    else:
                        visited_dirs.add(rp)
                        list_target = rp
            except Exception:
                pass
