            is_dir_e = False
            lst = os.lstat(child_fs)
            is_dir_e = stat.S_ISDIR(lst.st_mode)
        except Exception:
            return False
        list_real = os.path.realpath(list_path)
        if ignore.use_git and de_name == ".git" and ignore.is_git_repo_dir(list_real):
            return True
        entry_real = os.path.join(list_real, de_name) if not os.path.isabs(child_fs) else os.path.normpath(child_fs)
        # real path without resolving the final symlink for ignore matching
        try:
            entry_real = os.path.join(list_real, de_name)
        except Exception:
            pass
        if ignore.is_ignored(entry_real, is_dir_e, list_real):
            return True
        return False

    if root.dfs:
        def dfs(list_path, child_depth):
            entries = entries_of(list_path)
            if entries is None:
                return
            for de in entries:
                child_fs = os.path.join(list_path, de.name)
                if filtered(child_fs, de.name, list_path):
                    continue
                target = handle_entry(child_fs, de.name, child_depth)
                if target is not None:
                    dfs(target, child_depth + 1)
