# ---------------------------------------------------------------------------
# Output formatting
# ---------------------------------------------------------------------------
def entry_name_style(entry):
    if entry is None or entry.is_archive_entry or entry.lstat is None:
        return None
    m = entry.lstat.st_mode
    if stat.S_ISLNK(m): return "1;36"
    if stat.S_ISDIR(m):
        if (m & 0o1000) and (m & 0o002): return "42;30"
        if m & 0o002: return "42;34"
        if m & 0o1000: return "44;37"
        return "1;34"
    if stat.S_ISFIFO(m): return "33"
    if stat.S_ISSOCK(m): return "1;35"
    if stat.S_ISCHR(m) or stat.S_ISBLK(m): return "1;33"
    if stat.S_ISREG(m):
        if m & 0o4000: return "41;37"
        if m & 0o2000: return "43;30"
        if m & 0o111: return "1;32"
    return None

def html_escape(s):
    return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")

def format_rows(query, rows):
    fmt = query.fmt
    labels = []
    for f in query.fields:
        lab = expr_label(f)
        if query.has_aggregate:
            lab = lab.lower()
        labels.append(lab)
    use_color = (not state.no_color) and fmt in ("tabs","lines") and _stdout_is_tty()
    prepared = []
    for row in rows:
        values = list(row.values)
        if use_color and row.entry is not None:
            style = entry_name_style(row.entry)
            if style:
                for idx, f in enumerate(query.fields):
                    if f[0] == "field" and f[1] == "name" and idx < len(values):
                        values[idx] = "\x1b[" + style + "m" + values[idx] + "\x1b[0m"
        prefix = None
        if row.entry is not None and row.entry.is_archive_entry:
            prefix = "[" + row.entry.archive.get("archive_abs","") + "]"
        prepared.append((values, prefix))
    if fmt == "tabs":
        out = []
        for values, prefix in prepared:
            row_vals = ([prefix] if prefix is not None else []) + values
            out.append("\t".join(row_vals) + "\n")
        out_write("".join(out))
    elif fmt == "lines":
        out = []
        for values, prefix in prepared:
            row_vals = ([prefix] if prefix is not None else []) + values
            for v in row_vals:
                out.append(v + "\n")
        out_write("".join(out))
    elif fmt == "list":
        out = []
        for values, prefix in prepared:
            row_vals = ([prefix] if prefix is not None else []) + values
            for v in row_vals:
                out.append(v + "\x00")
        out_write("".join(out))
    elif fmt == "csv":
        import csv, io
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n", quoting=csv.QUOTE_MINIMAL)
        for values, prefix in prepared:
            writer.writerow(([prefix] if prefix is not None else []) + values)
        out_write(buf.getvalue())
    elif fmt == "json":
        import json
        objs = []
        for values, prefix in prepared:
            obj = {}
            if prefix is not None:
                obj["archive"] = prefix
            for lab, v in zip(labels, values):
                obj[lab] = v
            objs.append(obj)
        out_write(json.dumps(objs, ensure_ascii=False, separators=(",", ":"), sort_keys=True))
    elif fmt == "html":
        title = html_escape(query.raw)
        parts = ["<html><head><title>", title, "</title></head><body><table>",
                 '<tr><th colspan="%d">' % len(query.fields), title, "</th></tr>"]
        for values, prefix in prepared:
            row_vals = ([prefix] if prefix is not None else []) + values
            parts.append("<tr>")
            for v in row_vals:
                parts.append("<td>" + html_escape(v) + "</td>")
            parts.append("</tr>")
        parts.append("</table></body></html>")
        out_write("".join(parts))

def _stdout_is_tty():
    try:
        return sys.stdout.isatty()
    except Exception:
        return False

def perform_query(toks, raw_title):
    global _subquery_cache
    _subquery_cache = {}
    state.had_io_error = False
    state.had_parse_error = False
    try:
        query = parse_query_tokens(toks, raw_title)
    except ParseError_ as e:
        report_parse(e.message)
        return 2
    query.raw = raw_title
    rows = execute_query(query)
    format_rows(query, rows)
    return 1 if state.had_io_error else 0

def perform_query_string(qstr):
    try:
        toks = lex(qstr)
    except ParseError_ as e:
        report_parse(e.message)
        return 2
    return perform_query(toks, qstr)

# ---------------------------------------------------------------------------
# Interactive mode
# ---------------------------------------------------------------------------
def interactive_mode():
    is_tty = False
    try:
        is_tty = sys.stdin.isatty()
    except Exception:
        pass
    while True:
        line = None
        try:
            if is_tty:
                line = input("query> ")
            else:
                line = sys.stdin.readline()
                if line == "":
                    raise EOFError
                line = line.rstrip("\n").rstrip("\r")
        except EOFError:
            out_write("CTRL-D\n")
            break
        except KeyboardInterrupt:
            out_write("CTRL-C\n")
            break
        stripped = line.strip()
        low = stripped.lower()
        if low in ("quit", "exit"):
            break
        if low == "help":
            out_write(help_text_long(state.config))
            continue
        if low == "pwd":
            out_write(os.getcwd() + "\n")
            continue
        parts = stripped.split(None, 1)
        if parts and parts[0].lower() == "cd":
            if len(parts) < 2:
                report("cd", "no path specified")
            else:
                target = strip_outer_quotes(parts[1].strip())
                try:
                    os.chdir(target)
                except OSError as e:
                    if e.errno:
                        report("cd", "%s (os error %d)" % (os.strerror(e.errno), e.errno))
                    else:
                        report("cd", str(e))
            continue
        if parts and parts[0].lower() == "errors":
            if low == "errors off":
                state.errors_on = False
            elif low == "errors on":
                state.errors_on = True
            status = "ON" if state.errors_on else "OFF"
            if not state.no_color:
                status = "\x1b[33m" + status + "\x1b[0m"
            out_write("Errors are " + status + "\n")
            continue
        perform_query_string(line)
    return 0

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main(argv):
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="surrogateescape")
        sys.stderr.reconfigure(encoding="utf-8", errors="surrogateescape")
    except Exception:
        pass
    args = argv[1:]
    state.config = load_default_config()
    state.us_dates = bool(state.config.us_dates)
    state.no_color = bool(state.config.no_color) or ("NO_COLOR" in os.environ)
    if args:
        first = args[0].lower()
        if ("help" in first) or first.startswith("-h") or first.startswith("/h") or first.startswith("/?"):
            out_write(help_text_long(state.config))
            return 0
        if ("version" in first) or first.startswith("-v"):
            out_write(intro_text())
            return 0
