    """Returns dict with duration/bitrate/freq/title/artist/album/year/genre (strings)."""
    res = {}
    if not data:
        return res
    # WAV duration
    if data[:4] == b"RIFF" and data[8:12] == b"WAVE":
        try:
            i = 12; byte_rate = None; data_len = None
            while i + 8 <= len(data):
                cid = data[i:i+4]; clen = int.from_bytes(data[i+4:i+8], "little")
                if cid == b"fmt " and clen >= 12:
                    byte_rate = int.from_bytes(data[i+16:i+20], "little")
                elif cid == b"data":
                    data_len = clen
                i += 8 + clen + (clen & 1)
            if byte_rate and data_len is not None:
                res["duration"] = str(int(data_len // byte_rate))
        except Exception:
            pass
        return res
    # MP4 duration from mvhd
    if len(data) >= 8 and data[4:8] == b"ftyp":
        try:
            pos = data.find(b"mvhd")
