            return None
        if node[0] == "arith":
            return check_expr(node[2]) or check_expr(node[3])
        if node[0] == "neg":
            return check_expr(node[1])
        return None
    def check_cond(node):
        if not isinstance(node, tuple) or node is None:
            return None
